CREATE OR REPLACE FUNCTION public.b2b_complete_provisioning_compensation(p_claim uuid, p_fence uuid, p_user uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r platform_private.b2b_provisioning_receipts;
BEGIN
 PERFORM platform_private.require_service_role();
 -- Acquire before receipt/profile locks, never wait for the trigger gate afterward.
 UPDATE cf_user_guards_v1.state SET revision=revision+1 WHERE singleton;
 IF NOT FOUND THEN RAISE EXCEPTION 'user_guard_unavailable' USING ERRCODE='PT503'; END IF;
 SELECT * INTO r FROM platform_private.b2b_provisioning_receipts WHERE id=p_claim FOR UPDATE;
 IF r.id IS NULL OR r.fence IS DISTINCT FROM p_fence OR r.user_id IS DISTINCT FROM p_user OR r.status<>'compensating' THEN
 RAISE EXCEPTION 'b2b_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 -- Auth deletion's cascades must have completed; never pretend cleanup succeeded.
 IF EXISTS(SELECT 1 FROM public.profiles WHERE user_id=p_user)
 OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p_user)
 OR EXISTS(SELECT 1 FROM auth.users WHERE id=p_user) THEN
  RAISE EXCEPTION 'b2b_compensation_pending' USING ERRCODE='42501'; END IF;
 -- Live schema has NO Auth FK on these two links. Delete only exact receipt
 -- descendants after proven own Auth removal; unrelated links fail closed.
 IF EXISTS(SELECT 1 FROM public.partner_users WHERE user_id=p_user AND
 (r.partner_id IS NULL OR partner_id IS DISTINCT FROM r.partner_id OR tenant_id IS DISTINCT FROM r.organization_id OR papel IS DISTINCT FROM (CASE WHEN 'parceiro_b2b'=ANY(COALESCE(r.external_roles,ARRAY[r.external_role])) THEN 'gestor' ELSE 'tecnico' END)))
 OR EXISTS(SELECT 1 FROM public.user_clientes WHERE user_id=p_user AND
 (NOT (cliente_id=ANY(r.cliente_ids)) OR assigned_by IS DISTINCT FROM r.actor_id)) THEN
 RAISE EXCEPTION 'b2b_compensation_pending' USING ERRCODE='42501'; END IF;
 DELETE FROM public.partner_users WHERE user_id=r.user_id AND partner_id=r.partner_id AND tenant_id=r.organization_id AND papel=(CASE WHEN 'parceiro_b2b'=ANY(COALESCE(r.external_roles,ARRAY[r.external_role])) THEN 'gestor' ELSE 'tecnico' END);
 DELETE FROM public.user_clientes WHERE user_id=r.user_id AND cliente_id=ANY(r.cliente_ids) AND assigned_by=r.actor_id;
 UPDATE platform_private.b2b_provisioning_receipts SET status='aborted'
 WHERE id=p_claim AND fence=p_fence AND user_id=p_user AND status='compensating';
 IF NOT FOUND THEN RAISE EXCEPTION 'b2b_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_cc_upsert_item_price(p_id uuid, p_assignment_id uuid, p_plan_id uuid, p_buyer_scope text, p_partner_id uuid, p_customer_id uuid, p_product_id uuid, p_microrganismo_id uuid, p_unit_type text, p_volume_ml numeric, p_min_quantity numeric, p_pricing_mode text, p_condition_price numeric, p_discount_percent numeric, p_valid_from date, p_valid_until date, p_is_exception boolean, p_motivo text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_before jsonb;
BEGIN
 IF NOT platform_private.c2p1_item_allowed(p_assignment_id,p_plan_id,p_buyer_scope,p_partner_id,p_customer_id) THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF NOT public.fn_cc_can_prepare(auth.uid()) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF p_is_exception AND (p_motivo IS NULL OR length(btrim(p_motivo))=0) THEN
    RAISE EXCEPTION 'motivo_required_for_exception';
  END IF;
  PERFORM public.fn_cc_validate_item_input(p_plan_id, p_pricing_mode, p_condition_price, p_discount_percent);

  IF p_id IS NULL THEN
    INSERT INTO public.commercial_condition_item_prices
      (assignment_id,plan_id,buyer_scope,partner_id,customer_id,product_id,microrganismo_id,
       unit_type,volume_ml,min_quantity,pricing_mode,condition_price,discount_percent,
       valid_from,valid_until,is_exception,motivo,created_by,updated_by)
    VALUES (p_assignment_id,p_plan_id,p_buyer_scope,p_partner_id,p_customer_id,p_product_id,p_microrganismo_id,
       p_unit_type,p_volume_ml,COALESCE(p_min_quantity,0),p_pricing_mode,p_condition_price,p_discount_percent,
       COALESCE(p_valid_from,CURRENT_DATE),p_valid_until,COALESCE(p_is_exception,false),p_motivo,auth.uid(),auth.uid())
    RETURNING id INTO v_id;
    PERFORM public.fn_cc_audit('item_price',v_id,'create',NULL,
      to_jsonb((SELECT i FROM public.commercial_condition_item_prices i WHERE i.id=v_id)),p_motivo);
  ELSE
    SELECT to_jsonb(i) INTO v_before FROM public.commercial_condition_item_prices i WHERE i.id=p_id AND platform_private.c2p1_item_allowed(i.assignment_id,i.plan_id,i.buyer_scope,i.partner_id,i.customer_id) FOR UPDATE;
    IF v_before IS NULL THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
    IF (v_before->>'status') NOT IN ('draft','pending_approval') THEN RAISE EXCEPTION 'item_price_not_editable'; END IF;
    UPDATE public.commercial_condition_item_prices
       SET assignment_id=p_assignment_id, plan_id=p_plan_id, buyer_scope=p_buyer_scope,
           partner_id=p_partner_id, customer_id=p_customer_id, product_id=p_product_id,
           microrganismo_id=p_microrganismo_id, unit_type=p_unit_type, volume_ml=p_volume_ml,
           min_quantity=COALESCE(p_min_quantity,0), pricing_mode=p_pricing_mode,
           condition_price=p_condition_price, discount_percent=p_discount_percent,
           valid_from=COALESCE(p_valid_from,valid_from), valid_until=p_valid_until,
           is_exception=COALESCE(p_is_exception,false), motivo=p_motivo, updated_by=auth.uid()
     WHERE id=p_id RETURNING id INTO v_id;
    PERFORM public.fn_cc_audit('item_price',v_id,'update',v_before,
      to_jsonb((SELECT i FROM public.commercial_condition_item_prices i WHERE i.id=v_id)),p_motivo);
  END IF;
  RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION platform_private.tenant_email_settings_save(p_expected_version bigint, p_config jsonb, p_password text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_org uuid; v_version bigint; v_secret uuid;
BEGIN
 v_org:=platform_private.tenant_email_actor_org();
 IF v_org IS NULL THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM platform_private.tenant_email_require_review();
 IF p_expected_version IS NULL OR p_expected_version<0 OR p_expected_version>9007199254740991 THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 PERFORM platform_private.tenant_email_validate_config(p_config);
 IF p_password IS NOT NULL AND (length(p_password)<1 OR length(p_password)>4096 OR p_password ~ '[[:cntrl:]]') THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 -- Serializes first insertion and updates; hash collision only causes extra serialization.
 PERFORM pg_advisory_xact_lock(hashtextextended(v_org::text,0));
 -- Prevent revoke/inactivation during a queued operation from writing.
 IF platform_private.tenant_email_actor_org() IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM platform_private.tenant_email_require_review();
 SELECT version INTO v_version FROM public.communication_tenant_email_settings WHERE organization_id=v_org FOR UPDATE;
 v_version:=coalesce(v_version,0);
 IF p_expected_version<>v_version THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
 SELECT secret_id INTO v_secret FROM platform_private.communication_tenant_email_secret_refs WHERE organization_id=v_org;
 IF v_secret IS NULL AND p_password IS NULL THEN RAISE EXCEPTION 'SMTP_CREDENTIAL_REQUIRED' USING ERRCODE='22023'; END IF;
 IF p_password IS NOT NULL THEN
  IF v_secret IS NULL THEN
   v_secret:=vault.create_secret(p_password,'tenant_email_'||v_org::text,'');
   INSERT INTO platform_private.communication_tenant_email_secret_refs VALUES(v_org,v_secret);
  ELSE
   PERFORM vault.update_secret(v_secret,p_password,'tenant_email_'||v_org::text,'');
  END IF;
 END IF;
 INSERT INTO public.communication_tenant_email_settings(organization_id,config,version,credential_configured)
 VALUES(v_org,p_config,v_version+1,true)
 ON CONFLICT(organization_id) DO UPDATE SET config=EXCLUDED.config,version=EXCLUDED.version,
 credential_configured=true,state='DRAFT',sender_verified=false,dispatch_enabled=false,updated_at=now();
 INSERT INTO public.communication_tenant_email_audit(organization_id,actor_id,version,action)
 VALUES(v_org,auth.uid(),v_version+1,CASE WHEN p_password IS NULL THEN 'draft_saved' ELSE 'credential_rotated' END);
 RETURN platform_private.tenant_email_settings_get();
EXCEPTION
 WHEN SQLSTATE '42501' THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501';
 WHEN SQLSTATE '40001' THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001';
 WHEN SQLSTATE '22023' THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023';
 WHEN OTHERS THEN RAISE EXCEPTION 'SMTP_INTERNAL' USING ERRCODE='P0001';
END $function$

CREATE OR REPLACE FUNCTION platform_private.tenant_smtp_test_claim(p_mode text, p_version bigint, p_key uuid, p_confirm boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_org uuid; r platform_private.tenant_smtp_test_receipts; s public.communication_tenant_email_settings;
 v_id uuid:=gen_random_uuid(); v_out uuid:=gen_random_uuid(); v_event uuid:=gen_random_uuid(); v_fence uuid:=gen_random_uuid(); v_key text;
BEGIN
 v_org:=platform_private.tenant_email_actor_org();
 IF v_org IS NULL OR platform_private.tenant_smtp_test_actor(auth.uid()) IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF p_mode IS NULL OR p_mode NOT IN ('connection','send') OR p_version IS NULL OR p_version<1 OR p_version>9007199254740991 OR p_key IS NULL
 OR (p_mode='send' AND p_confirm IS DISTINCT FROM true) THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(v_org::text,0));
 IF platform_private.tenant_email_actor_org() IS DISTINCT FROM v_org OR platform_private.tenant_smtp_test_actor(auth.uid()) IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 SELECT * INTO s FROM public.communication_tenant_email_settings WHERE organization_id=v_org FOR UPDATE;
 IF s.version IS DISTINCT FROM p_version THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
 IF NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_gate WHERE approved AND id)
 OR s.config->>'port'<>'465' OR s.config->>'tls_mode'<>'implicit_tls' OR NOT s.credential_configured THEN RAISE EXCEPTION 'SMTP_UNAVAILABLE' USING ERRCODE='42501'; END IF;
 SELECT * INTO r FROM platform_private.tenant_smtp_test_receipts WHERE organization_id=v_org AND actor_id=auth.uid() AND request_key=p_key;
 IF FOUND THEN
  IF r.version<>p_version OR r.mode<>p_mode THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
  RETURN jsonb_build_object('replay',true,'code',coalesce(r.code,'SMTP_BUSY'),'version',r.version,'mode',r.mode,'dispatch_enabled',false,'sender_verified',false);
 END IF;
 -- Any abandoned/uncertain send blocks ALL future sends, even after version rotation.
 IF EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_receipts WHERE organization_id=v_org AND
 (state<>'complete' OR (p_mode='send' AND mode='send' AND code='smtp_send_ambiguous'))) THEN RAISE EXCEPTION 'SMTP_BUSY' USING ERRCODE='40001'; END IF;
 IF EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_receipts WHERE organization_id=v_org AND created_at>clock_timestamp()-interval '60 seconds') THEN RAISE EXCEPTION 'SMTP_COOLDOWN' USING ERRCODE='40001'; END IF;
 IF p_mode='send' AND NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_receipts WHERE organization_id=v_org AND actor_id=auth.uid()
 AND version=p_version AND mode='connection' AND code='smtp_connection_ok' AND state='complete' AND completed_at>clock_timestamp()-interval '5 minutes') THEN RAISE EXCEPTION 'SMTP_NOT_READY' USING ERRCODE='42501'; END IF;
 v_key:='tenant-smtp:'||v_org||':'||auth.uid()||':'||p_key;
 INSERT INTO public.comunicacao_eventos(id,event_key,source_type,source_id,created_by,idempotency_key,status,processed_at,payload)
 VALUES(v_event,'tenant.smtp.diagnostic','tenant_smtp_diagnostic_v1',v_org,auth.uid(),v_key,'processed',clock_timestamp(),'{}');
 INSERT INTO platform_private.tenant_smtp_test_insert_tickets VALUES(v_out,txid_current(),auth.uid(),v_org);
 INSERT INTO public.comunicacao_outbox(id,event_id,template_chave,template_versao,template_snapshot,canal,recipient_user_id,status,attempts,max_attempts,locked_by,lease_expires_at,idempotency_key)
 VALUES(v_out,v_event,'tenant_smtp_diagnostic_v1',1,'{}','email',auth.uid(),'processing',1,1,'tenant-smtp-test',NULL,v_key);
 IF NOT EXISTS(SELECT 1 FROM public.comunicacao_outbox WHERE id=v_out) THEN RAISE EXCEPTION 'SMTP_UNAVAILABLE'; END IF;
 DELETE FROM platform_private.tenant_smtp_test_insert_tickets WHERE outbox_id=v_out;
 INSERT INTO platform_private.tenant_smtp_test_receipts(id,organization_id,actor_id,version,actor_iat,mode,request_key,fence,outbox_id,state)
 VALUES(v_id,v_org,auth.uid(),p_version,coalesce((auth.jwt()->>'iat')::bigint,0),p_mode,p_key,v_fence,v_out,'claimed');
 INSERT INTO public.communication_tenant_email_audit(organization_id,actor_id,version,action) VALUES(v_org,auth.uid(),p_version,'smtp_test_'||p_mode||'_claimed');
 RETURN jsonb_build_object('replay',false,'job_id',v_id,'fence',v_fence);
END $function$

CREATE OR REPLACE FUNCTION tenant_smtp_executor.tenant_smtp_test_prepare(p_job uuid, p_fence uuid, p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r platform_private.tenant_smtp_test_receipts; s public.communication_tenant_email_settings; v_org uuid; v_password text; v_email text;
BEGIN
 SELECT organization_id INTO v_org FROM platform_private.tenant_smtp_test_receipts WHERE id=p_job;
 IF v_org IS NULL THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(v_org::text,0));
 SELECT * INTO r FROM platform_private.tenant_smtp_test_receipts WHERE id=p_job FOR UPDATE;
 IF r.actor_id IS DISTINCT FROM p_actor OR r.fence IS DISTINCT FROM p_fence OR r.state<>'claimed'
 OR platform_private.tenant_smtp_test_actor(p_actor) IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 -- Service JWT cannot substitute actor iat. Preserve claim's actual invitation fence.
 IF r.actor_iat<=0 OR EXISTS(SELECT 1 FROM public.platform_org_admin_invites i WHERE i.user_id=p_actor
 AND (i.access_operation_status='processing' OR (i.access_valid_after IS NOT NULL AND to_timestamp(r.actor_iat)<=i.access_valid_after))) THEN
 RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 SELECT * INTO s FROM public.communication_tenant_email_settings WHERE organization_id=v_org FOR UPDATE;
 IF s.version IS DISTINCT FROM r.version THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
 IF NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_gate WHERE approved AND id) OR s.config->>'port'<>'465'
 OR s.config->>'tls_mode'<>'implicit_tls' OR r.created_at<clock_timestamp()-interval '30 seconds' THEN RAISE EXCEPTION 'SMTP_UNAVAILABLE' USING ERRCODE='42501'; END IF;
 IF r.mode='send' AND NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_receipts WHERE organization_id=v_org AND actor_id=p_actor
 AND mode='connection' AND version=r.version AND code='smtp_connection_ok' AND completed_at>clock_timestamp()-interval '5 minutes') THEN RAISE EXCEPTION 'SMTP_NOT_READY' USING ERRCODE='42501'; END IF;
 SELECT email INTO v_email FROM auth.users WHERE id=p_actor AND email_confirmed_at IS NOT NULL;
 SELECT d.decrypted_secret INTO v_password FROM platform_private.communication_tenant_email_secret_refs t JOIN vault.decrypted_secrets d ON d.id=t.secret_id WHERE t.organization_id=v_org;
 IF v_password IS NULL OR v_email IS NULL THEN RAISE EXCEPTION 'SMTP_UNAVAILABLE' USING ERRCODE='42501'; END IF;
 UPDATE platform_private.tenant_smtp_test_receipts SET state='executing' WHERE id=p_job;
 RETURN jsonb_build_object('mode',r.mode,'version',r.version,'recipient',v_email,'config',s.config,'password',v_password);
EXCEPTION WHEN SQLSTATE '42501' THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501';
 WHEN SQLSTATE '40001' THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001';
 WHEN OTHERS THEN RAISE EXCEPTION 'SMTP_INTERNAL';
END $function$

CREATE OR REPLACE FUNCTION tenant_smtp_executor.tenant_smtp_test_finish(p_job uuid, p_fence uuid, p_actor uuid, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r platform_private.tenant_smtp_test_receipts; v_org uuid;
BEGIN
 SELECT organization_id INTO v_org FROM platform_private.tenant_smtp_test_receipts WHERE id=p_job;
 IF v_org IS NULL THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(v_org::text,0));
 SELECT * INTO r FROM platform_private.tenant_smtp_test_receipts WHERE id=p_job FOR UPDATE;
 IF r.actor_id IS DISTINCT FROM p_actor OR r.fence IS DISTINCT FROM p_fence OR r.state NOT IN ('executing','complete')
 THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF p_code IS NULL OR p_code NOT IN ('smtp_connection_ok','smtp_send_accepted','smtp_send_ambiguous','smtp_test_failed')
 OR (r.mode='connection' AND p_code IN ('smtp_send_accepted','smtp_send_ambiguous')) OR (r.mode='send' AND p_code='smtp_connection_ok') THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 IF r.state='complete' AND r.code<>p_code THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
 IF r.state<>'complete' THEN
 UPDATE platform_private.tenant_smtp_test_receipts SET state='complete',code=p_code,completed_at=clock_timestamp() WHERE id=p_job;
 UPDATE public.comunicacao_outbox SET status=CASE WHEN p_code='smtp_send_accepted' THEN 'sent'::public.comunicacao_outbox_status ELSE 'dead_letter'::public.comunicacao_outbox_status END,
 error_code=p_code,error_message=NULL,lease_expires_at=NULL,locked_by=NULL WHERE id=r.outbox_id;
 INSERT INTO public.communication_tenant_email_audit(organization_id,actor_id,version,action) VALUES(v_org,p_actor,r.version,p_code);
 END IF;
 -- Record results even if actor revoked after socket; never return result to revoked actor.
 RETURN jsonb_build_object('code',p_code,'version',r.version,'mode',r.mode,'dispatch_enabled',false,'sender_verified',false);
END $function$

CREATE OR REPLACE FUNCTION platform_private.tenant_smtp_sender_challenge_claim(p_version bigint, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_org uuid; s public.communication_tenant_email_settings; c platform_private.tenant_smtp_sender_challenges; v_id uuid:=gen_random_uuid(); v_fence uuid:=gen_random_uuid();
BEGIN
 v_org:=platform_private.tenant_smtp_f4_actor_org();
 IF p_version IS NULL OR p_version<1 OR p_version>9007199254740991 OR p_key IS NULL THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(v_org::text,0));
 v_org:=platform_private.tenant_smtp_f4_actor_org();
 PERFORM platform_private.tenant_smtp_f4_reconcile(v_org);
 SELECT * INTO s FROM public.communication_tenant_email_settings WHERE organization_id=v_org FOR UPDATE;
 IF s.version IS DISTINCT FROM p_version THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
 SELECT * INTO c FROM platform_private.tenant_smtp_sender_challenges WHERE organization_id=v_org AND actor_id=auth.uid() AND request_key=p_key;
 IF FOUND THEN
  IF c.version<>p_version THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
  RETURN jsonb_build_object('replay',true,'challenge_id',c.id,'state',c.state,'version',c.version);
 END IF;
 IF NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_f4_gate WHERE id AND approved) OR NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_gate WHERE id AND approved)
 OR s.config->>'port'<>'465' OR s.config->>'tls_mode'<>'implicit_tls' OR NOT s.credential_configured THEN RAISE EXCEPTION 'SMTP_UNAVAILABLE' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM platform_private.tenant_smtp_sender_challenges WHERE organization_id=v_org AND state IN ('claimed','executing'))
 OR EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_receipts WHERE organization_id=v_org AND state<>'complete') THEN RAISE EXCEPTION 'SMTP_BUSY' USING ERRCODE='40001'; END IF;
 IF EXISTS(SELECT 1 FROM platform_private.tenant_smtp_sender_challenges WHERE organization_id=v_org AND created_at>clock_timestamp()-interval '60 seconds') THEN RAISE EXCEPTION 'SMTP_COOLDOWN' USING ERRCODE='40001'; END IF;
 IF (SELECT count(*) FROM platform_private.tenant_smtp_sender_challenges WHERE organization_id=v_org AND created_at>clock_timestamp()-interval '24 hours')>=5 THEN RAISE EXCEPTION 'SMTP_QUOTA' USING ERRCODE='40001'; END IF;
 IF NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_receipts WHERE organization_id=v_org AND actor_id=auth.uid() AND version=p_version
  AND mode='connection' AND code='smtp_connection_ok' AND state='complete' AND completed_at>clock_timestamp()-interval '10 minutes') THEN RAISE EXCEPTION 'SMTP_NOT_READY' USING ERRCODE='42501'; END IF;
 -- A new challenge supersedes every open one (single valid code per tenant).
 UPDATE platform_private.tenant_smtp_sender_challenges SET state='invalidated',code_hash=NULL,code_salt=NULL,closed_at=clock_timestamp()
  WHERE organization_id=v_org AND state IN ('sent','ambiguous');
 INSERT INTO platform_private.tenant_smtp_sender_challenges(id,organization_id,actor_id,version,from_email,request_key,fence,actor_iat,state)
 VALUES(v_id,v_org,auth.uid(),p_version,lower(s.config->>'from_email'),p_key,v_fence,coalesce((auth.jwt()->>'iat')::bigint,0),'claimed');
 INSERT INTO public.communication_tenant_email_audit(organization_id,actor_id,version,action) VALUES(v_org,auth.uid(),p_version,'sender_challenge_claimed');
 RETURN jsonb_build_object('replay',false,'challenge_id',v_id,'fence',v_fence);
END $function$

CREATE OR REPLACE FUNCTION tenant_smtp_executor.tenant_smtp_sender_challenge_prepare(p_challenge uuid, p_fence uuid, p_actor uuid, p_salt text, p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c platform_private.tenant_smtp_sender_challenges; s public.communication_tenant_email_settings; v_password text;
BEGIN
 SELECT * INTO c FROM platform_private.tenant_smtp_sender_challenges WHERE id=p_challenge;
 IF c.id IS NULL THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(c.organization_id::text,0));
 SELECT * INTO c FROM platform_private.tenant_smtp_sender_challenges WHERE id=p_challenge FOR UPDATE;
 IF c.actor_id IS DISTINCT FROM p_actor OR c.fence IS DISTINCT FROM p_fence OR c.state<>'claimed'
 OR platform_private.tenant_smtp_test_actor(p_actor) IS DISTINCT FROM c.organization_id THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF c.actor_iat<=0 OR EXISTS(SELECT 1 FROM public.platform_org_admin_invites i WHERE i.user_id=p_actor
  AND (i.access_operation_status='processing' OR (i.access_valid_after IS NOT NULL AND to_timestamp(c.actor_iat)<=i.access_valid_after))) THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF p_salt IS NULL OR p_salt !~ '^[0-9a-f]{32}$' OR p_hash IS NULL OR p_hash !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 SELECT * INTO s FROM public.communication_tenant_email_settings WHERE organization_id=c.organization_id FOR UPDATE;
 IF s.version IS DISTINCT FROM c.version OR lower(s.config->>'from_email') IS DISTINCT FROM c.from_email THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
 IF NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_f4_gate WHERE id AND approved) OR NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_gate WHERE id AND approved)
 OR s.config->>'port'<>'465' OR s.config->>'tls_mode'<>'implicit_tls' OR c.created_at<clock_timestamp()-interval '30 seconds' THEN RAISE EXCEPTION 'SMTP_UNAVAILABLE' USING ERRCODE='42501'; END IF;
 SELECT d.decrypted_secret INTO v_password FROM platform_private.communication_tenant_email_secret_refs t JOIN vault.decrypted_secrets d ON d.id=t.secret_id WHERE t.organization_id=c.organization_id;
 IF v_password IS NULL THEN RAISE EXCEPTION 'SMTP_UNAVAILABLE' USING ERRCODE='42501'; END IF;
 UPDATE platform_private.tenant_smtp_sender_challenges SET state='executing',code_salt=p_salt,code_hash=p_hash,expires_at=clock_timestamp()+interval '15 minutes' WHERE id=p_challenge;
 RETURN jsonb_build_object('version',c.version,'recipient',c.from_email,'config',s.config,'password',v_password);
EXCEPTION WHEN SQLSTATE '42501' THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501';
 WHEN SQLSTATE '40001' THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001';
 WHEN SQLSTATE '22023' THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023';
 WHEN OTHERS THEN RAISE EXCEPTION 'SMTP_INTERNAL';
END $function$

CREATE OR REPLACE FUNCTION tenant_smtp_executor.tenant_smtp_sender_challenge_finish(p_challenge uuid, p_fence uuid, p_actor uuid, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c platform_private.tenant_smtp_sender_challenges; v_state text;
BEGIN
 SELECT * INTO c FROM platform_private.tenant_smtp_sender_challenges WHERE id=p_challenge;
 IF c.id IS NULL THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(c.organization_id::text,0));
 SELECT * INTO c FROM platform_private.tenant_smtp_sender_challenges WHERE id=p_challenge FOR UPDATE;
 IF c.actor_id IS DISTINCT FROM p_actor OR c.fence IS DISTINCT FROM p_fence THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF p_code IS NULL OR p_code NOT IN ('challenge_sent','challenge_ambiguous','challenge_failed') THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 v_state:=CASE p_code WHEN 'challenge_sent' THEN 'sent' WHEN 'challenge_ambiguous' THEN 'ambiguous' ELSE 'failed' END;
 IF c.state='executing' THEN
  -- Failed: discard hash; ambiguous: keep confirmable (code arrival proves possession), never auto-resend.
  UPDATE platform_private.tenant_smtp_sender_challenges SET state=v_state,
   code_hash=CASE WHEN v_state='failed' THEN NULL ELSE code_hash END, code_salt=CASE WHEN v_state='failed' THEN NULL ELSE code_salt END,
   closed_at=CASE WHEN v_state='failed' THEN clock_timestamp() END WHERE id=p_challenge;
  INSERT INTO public.communication_tenant_email_audit(organization_id,actor_id,version,action) VALUES(c.organization_id,p_actor,c.version,'sender_'||p_code);
 ELSIF c.state IS DISTINCT FROM v_state AND c.state NOT IN ('invalidated','verified','exhausted','expired') THEN
  RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001';
 END IF;
 RETURN jsonb_build_object('code',p_code,'version',c.version,'dispatch_enabled',false);
END $function$

CREATE OR REPLACE FUNCTION tenant_smtp_executor.tenant_smtp_lane_claim(p_worker text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE j platform_private.tenant_smtp_dispatch_jobs; s public.communication_tenant_email_settings; v_email text; v_password text; v_fence uuid;
 o public.comunicacao_outbox; v_num text; v_body text; v_reason text; v_org uuid;
BEGIN
 IF p_worker IS NULL OR p_worker !~ '^[A-Za-z0-9._-]{1,80}$' THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 FOR j IN SELECT * FROM platform_private.tenant_smtp_dispatch_jobs WHERE state IN ('executing','authorized') AND lease_expires_at<clock_timestamp() FOR UPDATE SKIP LOCKED LOOP
  IF j.state='executing' THEN
   UPDATE platform_private.tenant_smtp_dispatch_jobs SET state='failed',result_code='lease_expired_before_auth',finished_at=clock_timestamp() WHERE outbox_id=j.outbox_id;
   UPDATE public.comunicacao_outbox SET status='failed',error_code='tenant_smtp_lease_expired_before_auth',locked_by=NULL WHERE id=j.outbox_id;
   PERFORM platform_private.tenant_smtp_lane_log(j,'reconciled','lease_expired_before_auth',NULL);
  ELSE
   UPDATE platform_private.tenant_smtp_dispatch_jobs SET state='lease_expired',result_code='lease_expired_after_auth',finished_at=clock_timestamp() WHERE outbox_id=j.outbox_id;
   UPDATE public.comunicacao_outbox SET status='dead_letter',error_code='tenant_smtp_lease_expired',locked_by=NULL WHERE id=j.outbox_id;
   PERFORM platform_private.tenant_smtp_lane_log(j,'reconciled','lease_expired_after_auth',NULL);
  END IF;
 END LOOP;
 FOR j IN SELECT * FROM platform_private.tenant_smtp_dispatch_jobs WHERE state='queued' AND created_at<clock_timestamp()-interval '24 hours' FOR UPDATE SKIP LOCKED LOOP
  PERFORM platform_private.tenant_smtp_lane_cancel(j,'stale_queue',NULL);
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_dispatch_gate WHERE id AND approved) THEN RETURN NULL; END IF;
 INSERT INTO platform_private.tenant_smtp_lane_heartbeat VALUES(true,p_worker,clock_timestamp()) ON CONFLICT(id) DO UPDATE SET worker=EXCLUDED.worker,seen_at=EXCLUDED.seen_at;
 FOR v_org IN SELECT q.organization_id FROM platform_private.tenant_smtp_dispatch_jobs q WHERE q.state='queued'
  GROUP BY q.organization_id ORDER BY min(q.created_at) LIMIT 25 LOOP
  IF NOT pg_try_advisory_xact_lock(hashtextextended(v_org::text,0)) THEN CONTINUE; END IF;
  SELECT * INTO s FROM public.communication_tenant_email_settings WHERE organization_id=v_org FOR SHARE;
  IF NOT tenant_smtp_executor.tenant_smtp_dispatch_ready(v_org) THEN
   PERFORM platform_private.tenant_smtp_lane_cancel_queued(v_org,'tenant_not_ready',NULL); CONTINUE;
  END IF;
  IF (SELECT count(*) FROM platform_private.tenant_smtp_dispatch_jobs WHERE organization_id=v_org
   AND state IN ('executing','authorized','sent','ambiguous','lease_expired') AND started_at>clock_timestamp()-interval '1 hour')>=20 THEN CONTINUE; END IF;
  SELECT d.decrypted_secret INTO v_password FROM platform_private.communication_tenant_email_secret_refs t JOIN vault.decrypted_secrets d ON d.id=t.secret_id WHERE t.organization_id=v_org;
  IF v_password IS NULL THEN CONTINUE; END IF;
  FOR j IN SELECT * FROM platform_private.tenant_smtp_dispatch_jobs WHERE organization_id=v_org AND state='queued' ORDER BY created_at LIMIT 5 FOR UPDATE SKIP LOCKED LOOP
   IF s.version IS DISTINCT FROM j.version THEN PERFORM platform_private.tenant_smtp_lane_cancel(j,'tenant_not_ready',NULL); CONTINUE; END IF;
   v_reason:=platform_private.tenant_smtp_lane_source_reason(j.source_id,j.cliente_id,j.organization_id,j.recipient_user_id);
   IF v_reason IS NOT NULL THEN PERFORM platform_private.tenant_smtp_lane_cancel(j,v_reason,NULL); CONTINUE; END IF;
   SELECT * INTO o FROM public.comunicacao_outbox WHERE id=j.outbox_id FOR UPDATE;
   IF o.recipient_user_id IS DISTINCT FROM j.recipient_user_id OR o.status<>'processing' OR o.template_chave<>j.contract OR o.attempts<>0 THEN
    PERFORM platform_private.tenant_smtp_lane_cancel(j,'outbox_mismatch',NULL); CONTINUE;
   END IF;
   v_email:=platform_private.tenant_smtp_lane_recipient(j.organization_id,j.recipient_user_id);
   IF v_email IS NULL THEN PERFORM platform_private.tenant_smtp_lane_cancel(j,'recipient_unproven',NULL); CONTINUE; END IF;
   v_fence:=gen_random_uuid();
   UPDATE platform_private.tenant_smtp_dispatch_jobs SET state='executing',fence=v_fence,worker=p_worker,lease_expires_at=clock_timestamp()+interval '45 seconds',started_at=clock_timestamp(),
    recipient_hash=platform_private.tenant_smtp_lane_recipient_hash(j.outbox_id,v_email) WHERE outbox_id=j.outbox_id;
   UPDATE public.comunicacao_outbox SET attempts=1,locked_at=clock_timestamp() WHERE id=j.outbox_id;
   PERFORM platform_private.tenant_smtp_lane_log(j,'claimed',NULL,NULL);
   v_num:=coalesce(o.payload_snapshot->>'numero','');
   v_body:='Uma solicitação técnica foi atribuída a você'||CASE WHEN v_num<>'' THEN ' (nº '||v_num||')' ELSE '' END||'.'||chr(10)||
    'Tipo: '||coalesce(o.payload_snapshot->>'tipo_demanda','-')||chr(10)||'Urgência: '||coalesce(o.payload_snapshot->>'urgencia','-')||chr(10)||
    'Acesse o painel Cultivo Farm para ver os detalhes. Esta mensagem é automática.';
   RETURN jsonb_build_object('outbox_id',j.outbox_id,'fence',v_fence,'version',j.version,'recipient',v_email,
    'subject',left('Nova solicitação atribuída'||CASE WHEN v_num<>'' THEN ' — nº '||v_num ELSE '' END,200),'text',v_body,
    'config',s.config,'password',v_password);
  END LOOP;
 END LOOP;
 RETURN NULL;
EXCEPTION WHEN SQLSTATE '22023' THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023';
 WHEN OTHERS THEN RAISE EXCEPTION 'SMTP_INTERNAL';
END $function$

CREATE OR REPLACE FUNCTION tenant_smtp_executor.tenant_smtp_lane_authorize(p_outbox uuid, p_fence uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE j platform_private.tenant_smtp_dispatch_jobs; s public.communication_tenant_email_settings; v_reason text; v_email text;
BEGIN
 IF p_outbox IS NULL OR p_fence IS NULL THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 SELECT * INTO j FROM platform_private.tenant_smtp_dispatch_jobs WHERE outbox_id=p_outbox FOR UPDATE;
 IF NOT FOUND OR j.fence IS DISTINCT FROM p_fence THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
 IF j.state<>'executing' OR j.lease_expires_at IS NULL OR j.lease_expires_at<=clock_timestamp() THEN
  RETURN jsonb_build_object('ok',false,'reason','lease_lost');
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(j.organization_id::text,0));
 SELECT * INTO s FROM public.communication_tenant_email_settings WHERE organization_id=j.organization_id FOR SHARE;
 IF NOT tenant_smtp_executor.tenant_smtp_dispatch_ready(j.organization_id) OR s.version IS DISTINCT FROM j.version THEN v_reason:='tenant_not_ready';
 ELSE v_reason:=platform_private.tenant_smtp_lane_source_reason(j.source_id,j.cliente_id,j.organization_id,j.recipient_user_id); END IF;
 IF v_reason IS NULL THEN
  v_email:=platform_private.tenant_smtp_lane_recipient(j.organization_id,j.recipient_user_id);
  IF v_email IS NULL OR j.recipient_hash IS NULL OR platform_private.tenant_smtp_lane_recipient_hash(j.outbox_id,v_email)<>j.recipient_hash THEN v_reason:='recipient_changed'; END IF;
 END IF;
 IF v_reason IS NOT NULL THEN
  PERFORM platform_private.tenant_smtp_lane_cancel(j,v_reason,NULL);
  PERFORM platform_private.tenant_smtp_lane_log(j,'withheld',v_reason,NULL);
  RETURN jsonb_build_object('ok',false,'reason',v_reason);
 END IF;
 UPDATE platform_private.tenant_smtp_dispatch_jobs SET state='authorized',authorized_at=clock_timestamp(),lease_expires_at=clock_timestamp()+interval '30 seconds' WHERE outbox_id=p_outbox;
 PERFORM platform_private.tenant_smtp_lane_log(j,'authorized',NULL,NULL);
 RETURN jsonb_build_object('ok',true);
END $function$

CREATE OR REPLACE FUNCTION tenant_smtp_executor.tenant_smtp_lane_finish(p_outbox uuid, p_fence uuid, p_outcome text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE j platform_private.tenant_smtp_dispatch_jobs;
BEGIN
 IF p_outcome IS NULL OR p_outcome NOT IN ('sent','failed','ambiguous') OR p_outbox IS NULL OR p_fence IS NULL THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 SELECT * INTO j FROM platform_private.tenant_smtp_dispatch_jobs WHERE outbox_id=p_outbox FOR UPDATE;
 IF NOT FOUND OR j.fence IS DISTINCT FROM p_fence THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
 IF j.state='lease_expired' THEN
  PERFORM platform_private.tenant_smtp_lane_log(j,'late_finish','late_'||p_outcome,NULL);
  RETURN jsonb_build_object('state','lease_expired','replay',true,'lost',true);
 END IF;
 IF j.state IN ('sent','failed','ambiguous','cancelled') THEN
  IF j.state=p_outcome THEN RETURN jsonb_build_object('state',j.state,'replay',true,'lost',false); END IF;
  RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001';
 END IF;
 IF j.state='executing' AND p_outcome<>'failed' THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
 UPDATE platform_private.tenant_smtp_dispatch_jobs SET state=p_outcome,result_code='smtp_'||p_outcome,finished_at=clock_timestamp(),lease_expires_at=NULL WHERE outbox_id=p_outbox;
 UPDATE public.comunicacao_outbox SET status=(CASE p_outcome WHEN 'sent' THEN 'sent' WHEN 'failed' THEN 'failed' ELSE 'dead_letter' END)::public.comunicacao_outbox_status,
  sent_at=CASE WHEN p_outcome='sent' THEN clock_timestamp() END,error_code=CASE WHEN p_outcome='sent' THEN NULL ELSE 'tenant_smtp_'||p_outcome END,locked_by=NULL
  WHERE id=p_outbox;
 PERFORM platform_private.tenant_smtp_lane_log(j,p_outcome,NULL,NULL);
 RETURN jsonb_build_object('state',p_outcome,'replay',false,'lost',false);
END $function$

CREATE OR REPLACE FUNCTION finance_private.set_payable_allocations(p_payable_id uuid, p_allocations jsonb, p_reason text, p_expected_version integer, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u uuid:=auth.uid(); a public.accounts_payable%ROWTYPE; current_version integer; line jsonb; cc uuid; amt numeric; sm numeric:=0; seen uuid[]:='{}'; normalized jsonb:='[]'; enriched jsonb:='[]'; nm text; cd text; fp text; prior public.payable_allocation_versions%ROWTYPE; result_id uuid;
BEGIN
 IF u IS NULL OR public.is_financial_staff(u) IS NOT TRUE THEN RAISE EXCEPTION 'FIN_ALLOCATION_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF p_request_key IS NULL OR p_expected_version IS NULL OR p_expected_version<0 THEN RAISE EXCEPTION 'FIN_ALLOCATION_REQUEST' USING ERRCODE='23514'; END IF;
 IF p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'FIN_ALLOCATION_REASON' USING ERRCODE='23514'; END IF;
 IF jsonb_typeof(p_allocations) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'FIN_ALLOCATION_ITEMS' USING ERRCODE='23514'; END IF;
 IF jsonb_array_length(p_allocations) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'FIN_ALLOCATION_ITEMS' USING ERRCODE='23514'; END IF;
 FOR line IN SELECT value FROM jsonb_array_elements(p_allocations) LOOP
  IF jsonb_typeof(line) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'FIN_ALLOCATION_ITEMS' USING ERRCODE='23514'; END IF;
  BEGIN cc:=(line->>'cost_center_id')::uuid; amt:=(line->>'amount')::numeric;
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RAISE EXCEPTION 'FIN_ALLOCATION_VALUE' USING ERRCODE='23514'; END;
  IF cc IS NULL OR cc=ANY(seen) OR amt IS NULL OR amt::text IN('NaN','Infinity','-Infinity') OR amt<=0 OR amt<>round(amt,2) THEN RAISE EXCEPTION 'FIN_ALLOCATION_VALUE' USING ERRCODE='23514'; END IF;
  seen:=array_append(seen,cc);sm:=sm+amt;
  normalized:=normalized||jsonb_build_array(jsonb_build_object('cost_center_id',cc,'amount',round(amt,2)));
 END LOOP;
 SELECT jsonb_agg(x ORDER BY x->>'cost_center_id') INTO normalized FROM jsonb_array_elements(normalized) x;
 fp:=md5(jsonb_build_object('items',normalized,'reason',btrim(p_reason),'expected_version',p_expected_version)::text);
 SELECT * INTO a FROM public.accounts_payable WHERE id=p_payable_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'FIN_ALLOCATION_NOT_FOUND' USING ERRCODE='P0002'; END IF;
 SELECT * INTO prior FROM public.payable_allocation_versions WHERE payable_id=p_payable_id AND request_key=p_request_key;
 IF FOUND THEN
  IF prior.request_fingerprint<>fp THEN RAISE EXCEPTION 'FIN_ALLOCATION_IDEMPOTENCY_CONFLICT' USING ERRCODE='23514'; END IF;
  RETURN jsonb_build_object('success',true,'id',prior.id,'version',prior.version,'replayed',true);
 END IF;
 IF a.status='CANCELED' THEN RAISE EXCEPTION 'FIN_ALLOCATION_CANCELED' USING ERRCODE='23514'; END IF;
 SELECT coalesce(max(version),0) INTO current_version FROM public.payable_allocation_versions WHERE payable_id=p_payable_id;
 IF current_version<>p_expected_version THEN RAISE EXCEPTION 'FIN_ALLOCATION_STALE' USING ERRCODE='23514'; END IF;
 IF sm<>a.total_amount THEN RAISE EXCEPTION 'FIN_ALLOCATION_SUM' USING ERRCODE='23514'; END IF;
 FOR line IN SELECT value FROM jsonb_array_elements(normalized) LOOP
  cc:=(line->>'cost_center_id')::uuid;
  SELECT name,code INTO nm,cd FROM public.financial_cost_centers WHERE id=cc AND active FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'FIN_ALLOCATION_CENTER_INACTIVE' USING ERRCODE='23514'; END IF;
  enriched:=enriched||jsonb_build_array(line||jsonb_build_object('cost_center_name',nm,'cost_center_code',cd));
 END LOOP;
 INSERT INTO public.payable_allocation_versions(payable_id,version,total_amount,allocations,reason,request_key,request_fingerprint,created_by)
 VALUES(p_payable_id,current_version+1,a.total_amount,enriched,btrim(p_reason),p_request_key,fp,u) RETURNING id INTO result_id;
 UPDATE public.accounts_payable SET cost_center_id=CASE WHEN jsonb_array_length(enriched)=1 THEN (enriched->0->>'cost_center_id')::uuid ELSE NULL END WHERE id=p_payable_id;
 INSERT INTO public.financial_audit_log(entity_type,entity_id,action,old_data,new_data,performed_by,reason)
 VALUES('accounts_payable',p_payable_id,'COST_ALLOCATION_VERSION_CREATED',jsonb_build_object('version',current_version,'cost_center_id',a.cost_center_id),jsonb_build_object('allocation_id',result_id,'version',current_version+1,'reason',btrim(p_reason),'allocations',enriched),u,btrim(p_reason));
 RETURN jsonb_build_object('success',true,'id',result_id,'version',current_version+1,'replayed',false);
END $function$

CREATE OR REPLACE FUNCTION finance_private.protect_allocated_payable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v public.payable_allocation_versions%ROWTYPE; expected_center uuid;
BEGIN
 SELECT * INTO v FROM public.payable_allocation_versions WHERE payable_id=NEW.id ORDER BY version DESC LIMIT 1;
 IF NOT FOUND THEN RETURN NEW; END IF;
 IF NEW.total_amount IS DISTINCT FROM v.total_amount THEN RAISE EXCEPTION 'FIN_ALLOCATION_TOTAL_LOCKED' USING ERRCODE='23514'; END IF;
 expected_center:=CASE WHEN jsonb_array_length(v.allocations)=1 THEN (v.allocations->0->>'cost_center_id')::uuid ELSE NULL END;
 IF NEW.cost_center_id IS DISTINCT FROM expected_center THEN RAISE EXCEPTION 'FIN_ALLOCATION_USE_RPC' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.rpc_estoque_reservar_v1(p_os_id uuid, p_origem text, p_itens jsonb, p_idempotency_key text, p_dados jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_org uuid; v_actor uuid:=auth.uid(); v_tipo text; v_cliente uuid; v_partner uuid; v_order uuid; v_obs text;
 v_item jsonb; v_qty numeric; v_id uuid; v_payload jsonb; v_items jsonb; v_fp text; v_key text;
 v_prev platform_private.stock_batch_requests%ROWTYPE; v_result jsonb; v_call jsonb; v_ids uuid[]:=ARRAY[]::uuid[];
BEGIN
 v_org:=platform_private.stock_motor_actor('reserva');
 PERFORM platform_private.stock_motor_context_set(NULL);
 IF p_os_id IS NULL THEN RAISE EXCEPTION 'ESTQ_OS_OBRIGATORIA' USING ERRCODE='23514'; END IF;
 IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key))<8 OR length(p_idempotency_key)>200 THEN RAISE EXCEPTION 'ESTQ_IDEMPOTENCY_OBRIGATORIA' USING ERRCODE='23514'; END IF;
 IF p_origem IS NULL OR p_origem NOT IN ('padrao','manual','onfarm','on_farm','b2b') THEN RAISE EXCEPTION 'ESTQ_REFERENCE_UNSUPPORTED' USING ERRCODE='42501'; END IF;
 v_tipo:=CASE WHEN p_origem='padrao' THEN 'manual' WHEN p_origem='on_farm' THEN 'onfarm' ELSE p_origem END;
 IF p_dados IS NULL OR jsonb_typeof(p_dados)<>'object' THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each(p_dados) e WHERE e.key NOT IN ('cliente_id','partner_id','partner_order_id','observacao') OR jsonb_typeof(e.value) NOT IN ('string','null')) THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
 IF p_itens IS NULL OR jsonb_typeof(p_itens)<>'array' THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
 IF jsonb_array_length(p_itens)=0 THEN RAISE EXCEPTION 'ESTQ_ITENS_VAZIOS' USING ERRCODE='23514'; END IF;
 v_cliente:=nullif(p_dados->>'cliente_id','')::uuid; v_partner:=nullif(p_dados->>'partner_id','')::uuid; v_order:=nullif(p_dados->>'partner_order_id','')::uuid; v_obs:=nullif(p_dados->>'observacao','');
 v_payload:=jsonb_build_object('os_id',p_os_id,'os_tipo',v_tipo,'cliente_id',v_cliente,'partner_id',v_partner,'partner_order_id',v_order,'observacao',v_obs);
 v_items:='[]'::jsonb;
 FOR v_item IN SELECT value FROM jsonb_array_elements(p_itens) LOOP
  IF jsonb_typeof(v_item)<>'object' OR NOT(v_item ? 'item_id' AND v_item ? 'quantidade') THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_each(v_item) e WHERE e.key NOT IN ('item_id','quantidade') OR (e.key='item_id' AND jsonb_typeof(e.value)<>'string') OR (e.key='quantidade' AND jsonb_typeof(e.value) NOT IN ('string','number'))) THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
  v_id:=(v_item->>'item_id')::uuid; v_qty:=(v_item->>'quantidade')::numeric;
  IF v_qty IS NULL OR v_qty::text IN ('NaN','Infinity','-Infinity') OR v_qty<=0 THEN RAISE EXCEPTION 'ESTQ_QUANTIDADE_INVALIDA' USING ERRCODE='23514'; END IF;
  PERFORM platform_private.stock_motor_item(v_id,'reserva',v_payload);
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_items) e WHERE e->>'item_id'=v_id::text) THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
  v_items:=v_items||jsonb_build_array(jsonb_build_object('item_id',v_id,'quantidade',v_qty));
 END LOOP;
 SELECT jsonb_agg(value ORDER BY value->>'item_id') INTO v_items FROM jsonb_array_elements(v_items);
 v_fp:=md5(jsonb_build_object('actor',v_actor,'org',v_org,'os',p_os_id,'tipo',v_tipo,'payload',v_payload,'itens',v_items)::text);
 -- Global key collision is denied, never reused across actor/tenant/content. No wildcard comparisons.
 PERFORM pg_advisory_xact_lock(hashtextextended('stock_batch:'||p_idempotency_key,0));
 SELECT * INTO v_prev FROM platform_private.stock_batch_requests WHERE request_key=p_idempotency_key;
 IF FOUND THEN
  IF v_prev.actor IS DISTINCT FROM v_actor OR v_prev.organization_id IS DISTINCT FROM v_org OR v_prev.fingerprint IS DISTINCT FROM v_fp THEN RAISE EXCEPTION 'ESTQ_IDEMPOTENCY_CONFLITO' USING ERRCODE='23505'; END IF;
  RETURN v_prev.result||jsonb_build_object('replay',true);
 END IF;
 IF EXISTS(SELECT 1 FROM public.estoque_movimentacoes WHERE idempotency_key=p_idempotency_key OR left(idempotency_key,length(p_idempotency_key)+1)=p_idempotency_key||'#') THEN RAISE EXCEPTION 'ESTQ_IDEMPOTENCY_CONFLITO' USING ERRCODE='23505'; END IF;
 -- Consistent item order before nested motor calls; all writes are one transaction.
 FOR v_item IN SELECT value FROM jsonb_array_elements(v_items) LOOP
  v_id:=(v_item->>'item_id')::uuid;
  PERFORM 1 FROM public.estoque_produto WHERE id=v_id FOR UPDATE;
  PERFORM platform_private.stock_motor_item(v_id,'reserva',v_payload);
 END LOOP;
 FOR v_item IN SELECT value FROM jsonb_array_elements(v_items) LOOP
  v_id:=(v_item->>'item_id')::uuid; v_qty:=(v_item->>'quantidade')::numeric;
  v_key:='stock_batch_item:'||md5(jsonb_build_array(p_idempotency_key,v_actor,v_org,v_id)::text);
  IF EXISTS(SELECT 1 FROM public.estoque_movimentacoes WHERE idempotency_key=v_key OR left(idempotency_key,length(v_key)+1)=v_key||'#') THEN RAISE EXCEPTION 'ESTQ_IDEMPOTENCY_CONFLITO' USING ERRCODE='23505'; END IF;
  v_call:=public.rpc_estoque_operar_v1('reserva',v_id,v_qty,v_key,v_payload);
  IF v_call->>'ok' IS DISTINCT FROM 'true' OR v_call->>'replay' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'ESTQ_SEM_TRILHA'; END IF;
  -- The ledger is canonical for the split target, not the source item.
  SELECT estoque_produto_id INTO v_id FROM public.estoque_movimentacoes WHERE id=(v_call->>'movimentacao_id')::uuid;
  IF v_id IS NULL THEN RAISE EXCEPTION 'ESTQ_SEM_TRILHA'; END IF;
  v_ids:=array_append(v_ids,v_id);
 END LOOP;
 v_result:=jsonb_build_object('ok',true,'replay',false,'itens',to_jsonb(v_ids));
 INSERT INTO platform_private.stock_batch_requests(request_key,actor,organization_id,fingerprint,result) VALUES(p_idempotency_key,v_actor,v_org,v_fp,v_result);
 PERFORM platform_private.stock_motor_context_set(NULL);
 RETURN v_result;
END $function$

CREATE OR REPLACE FUNCTION platform_private.user_edit_f2_common(p_user uuid, p_stamp timestamp with time zone, p_profile jsonb, p_roles app_role[], p_clients uuid[], p_primary uuid, p_partner uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE org uuid; envelope jsonb:=p_profile->'_external_edit'; common jsonb:=p_profile-'_external_edit';
 current_roles public.app_role[]; before_version text; after_version text; req_hash text; receipt record;
 key uuid; reason text; stamp timestamptz; old_common jsonb; new_common jsonb; result jsonb; k text;
BEGIN
 -- Reject unauthorized callers before any global or target row lock.
 -- Repeat full authorization after locks to close concurrent permission changes.
 IF auth.uid() IS NULL
 OR platform_private.platform_actor_access_ready(auth.uid()) IS NOT TRUE
 OR platform_private.is_tenant_admin_for_user(p_user) IS NOT TRUE
 THEN RAISE EXCEPTION 'user_edit_forbidden' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM platform_private.user_edit_f2_gate WHERE singleton AND reviewed)
 THEN RAISE EXCEPTION 'user_edit_phase_closed' USING ERRCODE='42501'; END IF;
 -- Lock order shared with ALL existing identity/link DML (statement trigger).
 -- NOWAIT prevents reverse-order legacy writers from causing a deadlock; retry is explicit.
 PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'user_guard_unavailable' USING ERRCODE='PT503'; END IF;
 PERFORM 1 FROM platform_private.user_edit_f2_gate WHERE singleton AND reviewed FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'user_edit_phase_closed' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.profiles WHERE user_id IN (auth.uid(),p_user) ORDER BY user_id FOR UPDATE;
 org:=platform_private.user_edit_f2_authorize(p_user);
 PERFORM 1 FROM public.user_roles WHERE user_id IN (auth.uid(),p_user) ORDER BY user_id,id FOR UPDATE;
 PERFORM 1 FROM public.user_clientes WHERE user_id=p_user ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.partner_users WHERE user_id=p_user ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.clientes WHERE id IN (SELECT cliente_id FROM public.user_clientes WHERE user_id=p_user) ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.partner_accounts WHERE id IN (SELECT partner_id FROM public.partner_users WHERE user_id=p_user) ORDER BY id FOR SHARE;
 SELECT array_agg(role ORDER BY role::text) INTO current_roles FROM public.user_roles WHERE user_id=p_user;
 IF current_roles IS NULL OR cardinality(current_roles)<>1 OR current_roles[1] NOT IN ('cliente_produtor','parceiro_b2b')
 OR p_roles IS DISTINCT FROM current_roles THEN RAISE EXCEPTION 'user_edit_linked_role_unavailable' USING ERRCODE='42501'; END IF;
 IF cardinality(coalesce(p_clients,'{}'::uuid[]))<>0 OR p_primary IS NOT NULL OR p_partner IS NOT NULL THEN
  RAISE EXCEPTION 'user_edit_unscoped_links_forbidden' USING ERRCODE='42501'; END IF;
 -- Common-only path may preserve inactive/revoked links, but never adopt unowned ones.
 IF EXISTS(SELECT 1 FROM public.user_clientes u LEFT JOIN public.clientes c ON c.id=u.cliente_id WHERE u.user_id=p_user AND c.organization_id IS DISTINCT FROM org)
 OR EXISTS(SELECT 1 FROM public.partner_users u LEFT JOIN public.partner_accounts p ON p.id=u.partner_id WHERE u.user_id=p_user AND p.commercial_owner_organization_id IS DISTINCT FROM org)
 THEN RAISE EXCEPTION 'user_edit_forbidden' USING ERRCODE='42501'; END IF;
 IF jsonb_typeof(envelope) IS DISTINCT FROM 'object' OR envelope->>'mode' IS DISTINCT FROM 'common_preserve_links'
 OR EXISTS(SELECT 1 FROM jsonb_object_keys(envelope) x WHERE x NOT IN ('mode','expected_version','idempotency_key','reason'))
 OR jsonb_typeof(envelope->'expected_version') IS DISTINCT FROM 'string' OR (envelope->>'expected_version') !~ '^[a-f0-9]{64}$'
 OR jsonb_typeof(envelope->'idempotency_key') IS DISTINCT FROM 'string' OR (envelope->>'idempotency_key') !~* '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
 OR jsonb_typeof(envelope->'reason') IS DISTINCT FROM 'string' OR char_length(btrim(envelope->>'reason')) NOT BETWEEN 2 AND 500
 OR p_stamp IS NULL THEN RAISE EXCEPTION 'user_edit_invalid_input' USING ERRCODE='22023'; END IF;
 key:=(envelope->>'idempotency_key')::uuid; reason:=btrim(envelope->>'reason');
 -- Exactly these six payload fields are intentional (not a profiles column count).
 -- Omitting a nullable field must not silently clear it in a whole-form update.
 IF (SELECT count(*) FROM jsonb_object_keys(common))<>6 OR EXISTS(SELECT 1 FROM jsonb_object_keys(common) x WHERE x NOT IN ('nome','telefone','cargo','cpf_cnpj','crea','especialidade')) THEN
 RAISE EXCEPTION 'user_edit_invalid_fields' USING ERRCODE='22023'; END IF;
 FOR k IN SELECT jsonb_object_keys(common) LOOP
 IF jsonb_typeof(common->k) NOT IN ('string','null') OR char_length(coalesce(common->>k,''))>500 THEN RAISE EXCEPTION 'user_edit_invalid_fields' USING ERRCODE='22023'; END IF;
 END LOOP;
 IF jsonb_typeof(common->'nome') IS DISTINCT FROM 'string' OR char_length(btrim(common->>'nome')) NOT BETWEEN 2 AND 150 THEN RAISE EXCEPTION 'user_edit_invalid_name' USING ERRCODE='22023'; END IF;
 IF nullif(common->>'telefone','') IS NOT NULL AND (common->>'telefone') !~ '^[0-9]{10,11}$' THEN RAISE EXCEPTION 'user_edit_invalid_phone' USING ERRCODE='22023'; END IF;
 req_hash:=encode(extensions.digest(convert_to(jsonb_build_object('target',p_user,'stamp',p_stamp,'profile',p_profile,'roles',p_roles,'clients',p_clients,'primary',p_primary,'partner',p_partner)::text,'UTF8'),'sha256'),'hex');
 -- Authorization, target type, ownership and gates were revalidated BEFORE replay.
 SELECT * INTO receipt FROM platform_private.user_edit_f2_audit WHERE actor_id=auth.uid() AND organization_id=org AND idempotency_key=key;
 IF FOUND THEN
  IF receipt.request_hash IS DISTINCT FROM req_hash THEN RAISE EXCEPTION 'user_edit_idempotency_conflict' USING ERRCODE='PT409'; END IF;
  -- A retry after unrelated target changes must not present a stale result as current.
  IF receipt.version_after IS DISTINCT FROM platform_private.user_edit_f2_version(p_user) THEN RAISE EXCEPTION 'user_edit_conflict' USING ERRCODE='PT409'; END IF;
  RETURN receipt.result || jsonb_build_object('replayed',true);
 END IF;
 before_version:=platform_private.user_edit_f2_version(p_user);
 SELECT updated_at,jsonb_build_object('nome',nome,'telefone',telefone,'cargo',cargo,'cpf_cnpj',cpf_cnpj,'crea',crea,'especialidade',especialidade)
 INTO stamp,old_common FROM public.profiles WHERE user_id=p_user;
 IF before_version IS DISTINCT FROM envelope->>'expected_version' OR stamp IS DISTINCT FROM p_stamp THEN RAISE EXCEPTION 'user_edit_conflict' USING ERRCODE='PT409'; END IF;
 UPDATE public.profiles SET nome=btrim(common->>'nome'),telefone=nullif(common->>'telefone',''),cargo=nullif(common->>'cargo',''),cpf_cnpj=nullif(common->>'cpf_cnpj',''),crea=nullif(common->>'crea',''),especialidade=nullif(common->>'especialidade','')
 WHERE user_id=p_user RETURNING updated_at,jsonb_build_object('nome',nome,'telefone',telefone,'cargo',cargo,'cpf_cnpj',cpf_cnpj,'crea',crea,'especialidade',especialidade) INTO stamp,new_common;
 IF NOT FOUND THEN RAISE EXCEPTION 'user_edit_not_found' USING ERRCODE='P0002'; END IF;
 after_version:=platform_private.user_edit_f2_version(p_user);
 result:=jsonb_build_object('success',true,'user_id',p_user,'updated_at',stamp,'version',after_version,'replayed',false,'links_preserved',true);
 INSERT INTO platform_private.user_edit_f2_audit(actor_id,organization_id,target_id,idempotency_key,request_hash,reason,version_before,version_after,old_common,new_common,result)
 VALUES(auth.uid(),org,p_user,key,req_hash,reason,before_version,after_version,old_common,new_common,result);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION platform_private.c2_recover_order_attempt_core(p_partner uuid, p_expected_key text DEFAULT NULL::text, p_expected_generation bigint DEFAULT NULL::bigint, p_advance boolean DEFAULT false, p_ack_order uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '5s'
AS $function$
DECLARE uid uuid:=auth.uid(); org uuid; j platform_private.partner_order_attempt_journal;
  result jsonb; nextgen bigint; nextkey text; fresh uuid; predecessors jsonb;
BEGIN
 org := platform_private.c2_attempt_scope_lock(uid,p_partner);
 SELECT * INTO j FROM platform_private.partner_order_attempt_journal
 WHERE actor_id=uid AND organization_id=org AND partner_id=p_partner ORDER BY generation DESC LIMIT 1;
 -- Immutable journal links plus canonical committed receipts/closure tombstones.
 -- Read only: no inferred closure, no added locks, no client-supplied terminal proof.
 SELECT coalesce(jsonb_agg(jsonb_build_object('key',h.idempotency_key,'generation',h.generation,
   'state',CASE WHEN i.order_id IS NOT NULL THEN 'committed' WHEN c.idempotency_key IS NOT NULL THEN 'closed' ELSE 'unknown' END)
   || CASE WHEN i.order_id IS NOT NULL THEN jsonb_build_object('order_id',i.order_id,'numero',o.numero) ELSE '{}'::jsonb END
   ORDER BY h.generation),'[]'::jsonb) INTO predecessors
 FROM platform_private.partner_order_attempt_journal h
 LEFT JOIN public.partner_order_idempotency i ON i.partner_id=h.partner_id AND i.idempotency_key=h.idempotency_key AND i.created_by=uid
 LEFT JOIN public.partner_orders o ON o.id=i.order_id
 LEFT JOIN platform_private.partner_order_idempotency_closures c ON c.partner_id=h.partner_id AND c.idempotency_key=h.idempotency_key
 WHERE h.actor_id=uid AND h.organization_id=org AND h.partner_id=p_partner AND h.generation<j.generation;
 IF p_advance THEN
  IF j.idempotency_key IS NULL OR p_expected_key IS DISTINCT FROM j.idempotency_key
   OR p_expected_generation IS DISTINCT FROM j.generation THEN
   RAISE EXCEPTION 'C2DJ_CAS_CONFLICT' USING ERRCODE='PT409'; END IF;
  -- Explicit click only; existing atomic close is the ONLY way to abandon uncertain K.
  result := platform_private.c2_close_partner_order_attempt_core(p_partner,j.idempotency_key);
  SELECT organization_id INTO fresh FROM public.profiles WHERE user_id=uid AND ativo;
  IF fresh IS DISTINCT FROM org THEN RAISE EXCEPTION 'C2DJ_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
  IF result->>'state'='in_progress' THEN RETURN jsonb_build_object('contract','C2_ORDER_JOURNAL_V1','state','unknown'); END IF;
  IF result->>'state'='committed' AND p_ack_order IS DISTINCT FROM (result->>'order_id')::uuid THEN
   RETURN result || jsonb_build_object('contract','C2_ORDER_JOURNAL_V1','key',j.idempotency_key,'generation',j.generation,'predecessors',predecessors); END IF;
  IF result->>'state' NOT IN ('closed','committed') OR result->>'state' IS NULL THEN
   RAISE EXCEPTION 'C2DJ_INVALID_CLOSURE'; END IF;
  predecessors:=predecessors||jsonb_build_array(result||jsonb_build_object('key',j.idempotency_key,'generation',j.generation));
 ELSIF j.idempotency_key IS NOT NULL THEN
  -- Recovery is read-only with respect to closure; never auto-close an absent order.
  PERFORM pg_advisory_xact_lock(hashtextextended('b2b_idem:'||p_partner::text||':'||j.idempotency_key,0));
  PERFORM platform_private.c2_partner_order_attempt_authz(uid,p_partner);
  SELECT organization_id INTO fresh FROM public.profiles WHERE user_id=uid AND ativo;
  IF fresh IS DISTINCT FROM org THEN RAISE EXCEPTION 'C2DJ_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
  SELECT jsonb_build_object('state','committed','order_id',i.order_id,'numero',o.numero) INTO result
   FROM public.partner_order_idempotency i JOIN public.partner_orders o ON o.id=i.order_id
   WHERE i.partner_id=p_partner AND i.idempotency_key=j.idempotency_key AND i.created_by=uid;
  IF result IS NULL THEN
   result := jsonb_build_object('state',CASE WHEN EXISTS(SELECT 1 FROM platform_private.partner_order_idempotency_closures
    WHERE partner_id=p_partner AND idempotency_key=j.idempotency_key) THEN 'closed' ELSE 'uncertain' END);
  END IF;
  RETURN result || jsonb_build_object('contract','C2_ORDER_JOURNAL_V1','key',j.idempotency_key,'generation',j.generation,'predecessors',predecessors);
 ELSIF p_expected_key IS NOT NULL OR p_expected_generation IS NOT NULL THEN
  -- Lost legacy memory cannot be adopted by mere key knowledge.
  RAISE EXCEPTION 'C2DJ_LEGACY_RECONCILIATION_REQUIRED' USING ERRCODE='42501';
 END IF;
 nextgen := coalesce(j.generation,0)+1; nextkey := gen_random_uuid()::text;
 IF j.idempotency_key IS NULL AND EXISTS(SELECT 1 FROM public.partner_order_idempotency i
 WHERE i.created_by=uid AND i.partner_id=p_partner) THEN
  RAISE EXCEPTION 'C2DJ_LEGACY_RECONCILIATION_REQUIRED' USING ERRCODE='42501'; END IF;
 INSERT INTO platform_private.partner_order_attempt_journal(actor_id,organization_id,partner_id,generation,idempotency_key,predecessor_key)
 VALUES(uid,org,p_partner,nextgen,nextkey,j.idempotency_key);
 RETURN jsonb_build_object('contract','C2_ORDER_JOURNAL_V1','state','reserved','key',nextkey,'generation',nextgen,'predecessors',predecessors);
END $function$

CREATE OR REPLACE FUNCTION public.rpc_salvar_aplicacao_v1(p_aplicacao_id uuid, p_payload jsonb, p_rectify_id uuid DEFAULT NULL::uuid, p_evidencias jsonb DEFAULT '[]'::jsonb, p_evidencias_manter uuid[] DEFAULT '{}'::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 u uuid:=auth.uid(); org uuid; client uuid; product uuid; os_org uuid;
 osid uuid; onid uuid; lot uuid; responsible uuid; phase text; canonical jsonb; os_status text;
 r platform_private.application_save_preparations%ROWTYPE;
 original public.aplicacoes%ROWTYPE; a public.aplicacoes%ROWTYPE;
 ev jsonb; e public.aplicacao_evidencias%ROWTYPE; obj storage.objects%ROWTYPE;
 kept uuid; k text; n numeric; lo numeric; hi numeric; root uuid; ver integer:=1;
 expected text; ev_id uuid; moment date; start_at timestamptz; end_at timestamptz;
 manifest jsonb; count_files integer; own_role boolean; name_responsible text;
BEGIN
 -- Never parse/replay a receipt before proving current actor readiness.
 IF u IS NULL THEN RAISE EXCEPTION 'application_auth_required' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.profiles WHERE user_id=u FOR SHARE;
 org:=public.h15_actor_organization();
 IF org IS NULL THEN RAISE EXCEPTION 'application_actor_denied' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.organizations WHERE id=org FOR SHARE;
 PERFORM 1 FROM public.user_roles WHERE user_id=u ORDER BY role FOR SHARE;
 PERFORM 1 FROM public.platform_org_admin_invites WHERE user_id=u FOR SHARE;
 IF p_aplicacao_id IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_evidencias) IS DISTINCT FROM 'array' OR p_evidencias_manter IS NULL
 OR octet_length(p_payload::text)>32768 OR octet_length(p_evidencias::text)>32768 THEN
 RAISE EXCEPTION 'application_payload_invalid' USING ERRCODE='22023'; END IF;
 phase:=p_payload->>'_phase';
 IF phase IS NULL OR phase NOT IN ('prepare','finalize') THEN RAISE EXCEPTION 'application_phase_required' USING ERRCODE='22023'; END IF;
 canonical:=p_payload-'_phase';
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(canonical) key WHERE key NOT IN (
 'ordem_servico_id','ordem_servico_onfarm_id','data_aplicacao','hora_inicio','hora_fim','responsavel_id','responsavel',
 'modo_aplicacao','produto_usado_id','lote_usado_id','dose_aplicada','dose_unidade','volume_calda_l_ha',
 'volume_total_aplicado_ml','area_aplicada_ha','equipamento','equipamento_modelo','bico_tipo','pressao_bar',
 'temperatura_c','umidade_pct','vento_kmh','condicoes_climaticas','latitude','longitude','resultado_inicial',
 'observacoes','created_by','motivo_retificacao')) THEN RAISE EXCEPTION 'application_unknown_field' USING ERRCODE='22023'; END IF;
 IF canonical->>'created_by' IS DISTINCT FROM u::text OR canonical->>'dose_unidade' IS DISTINCT FROM 'mL/ha'
 THEN RAISE EXCEPTION 'application_author_or_unit_invalid' USING ERRCODE='42501'; END IF;
 osid:=nullif(canonical->>'ordem_servico_id','')::uuid;
 onid:=nullif(canonical->>'ordem_servico_onfarm_id','')::uuid;
 IF num_nonnulls(osid,onid)<>1 THEN RAISE EXCEPTION 'application_origin_invalid' USING ERRCODE='22023'; END IF;
 -- Lock every persisted authority before receipt lookup. Locks prevent UPDATE/DELETE races;
 -- they do not invent membership, roles or a tenant for NULL legacy rows.
 IF osid IS NOT NULL THEN
 SELECT cliente_id,produto_id,organization_id,status::text INTO client,product,os_org,os_status FROM public.ordens_servico WHERE id=osid FOR SHARE;
 ELSE
 SELECT cliente_id,produto_id,status::text INTO client,product,os_status FROM public.ordens_servico_onfarm WHERE id=onid FOR SHARE;
 SELECT organization_id INTO os_org FROM public.clientes WHERE id=client;
 END IF;
 IF client IS NULL OR os_org IS DISTINCT FROM org OR product IS NULL THEN RAISE EXCEPTION 'application_origin_denied' USING ERRCODE='42501'; END IF;
 -- Same lifecycle as the canonical desktop form. Replay is reauthorized too.
 IF os_status IS NULL OR NOT (os_status IN ('entregue','pronto_entrega','envase')
 OR (p_rectify_id IS NOT NULL AND os_status='finalizada')) THEN RAISE EXCEPTION 'application_os_status_denied' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.clientes WHERE id=client AND organization_id=org FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'application_client_denied' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.user_clientes WHERE user_id=u AND cliente_id=client ORDER BY id FOR SHARE;
 IF public.can_user_create_aplicacao_for_cliente(client) IS DISTINCT FROM true THEN RAISE EXCEPTION 'application_create_denied' USING ERRCODE='42501'; END IF;
 IF (public.has_role(u,'cliente_produtor') OR public.has_role(u,'consultor_tecnico') OR public.has_role(u,'tecnico_agronomo'))
 AND NOT (public.has_role(u,'administrador') OR public.has_role(u,'gestor') OR public.has_role(u,'administrativo'))
 AND NOT client=ANY(public.get_cliente_ids_for_user(u)) THEN RAISE EXCEPTION 'application_membership_denied' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.produtos WHERE id=product AND ativo IS TRUE FOR SHARE;
 IF NOT FOUND OR nullif(canonical->>'produto_usado_id','')::uuid IS DISTINCT FROM product THEN RAISE EXCEPTION 'application_product_denied' USING ERRCODE='42501'; END IF;
 lot:=nullif(canonical->>'lote_usado_id','')::uuid;
 IF lot IS NOT NULL THEN
 PERFORM 1 FROM public.lotes WHERE id=lot AND produto_id=product AND organization_id=org AND status='aprovado' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'application_lot_denied' USING ERRCODE='42501'; END IF; END IF;
 responsible:=nullif(canonical->>'responsavel_id','')::uuid;
 SELECT nome INTO name_responsible FROM public.profiles WHERE user_id=responsible AND organization_id=org
 AND ativo IS TRUE AND senha_provisoria IS FALSE FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'application_responsible_denied' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.user_roles WHERE user_id=responsible ORDER BY role FOR SHARE;
 IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=responsible AND role::text IN
 ('administrador','gestor','administrativo','consultor_tecnico','tecnico_agronomo','aplicador','operador_onfarm','cliente_produtor'))
 OR platform_private.platform_actor_access_ready(responsible) IS DISTINCT FROM true THEN RAISE EXCEPTION 'application_responsible_denied' USING ERRCODE='42501'; END IF;
 own_role:=public.has_role(u,'administrador') OR public.has_role(u,'gestor') OR public.has_role(u,'administrativo') OR public.has_role(u,'consultor_tecnico');
 IF NOT own_role AND responsible IS DISTINCT FROM u THEN RAISE EXCEPTION 'application_responsible_denied' USING ERRCODE='42501'; END IF;
 -- Preserve Storage1's applicator restriction; do not make RPC metadata a bypass.
 IF public.has_role(u,'aplicador') AND NOT own_role AND responsible IS DISTINCT FROM u
 AND NOT client=ANY(public.get_cliente_ids_for_user(u)) THEN RAISE EXCEPTION 'application_applicator_denied' USING ERRCODE='42501'; END IF;
 FOR k,lo,hi IN SELECT * FROM (VALUES
 ('dose_aplicada',0::numeric,NULL::numeric),('area_aplicada_ha',0::numeric,NULL::numeric),
 ('volume_calda_l_ha',0::numeric,NULL::numeric),('volume_total_aplicado_ml',0::numeric,NULL::numeric),
 ('pressao_bar',0::numeric,NULL::numeric),('temperatura_c',-50::numeric,70::numeric),('umidade_pct',0::numeric,100::numeric),
 ('vento_kmh',0::numeric,250::numeric),('latitude',-90::numeric,90::numeric),('longitude',-180::numeric,180::numeric)) bounds LOOP
 IF canonical->>k IS NULL THEN
 IF k IN ('dose_aplicada','area_aplicada_ha','volume_total_aplicado_ml') THEN RAISE EXCEPTION 'application_numeric_required' USING ERRCODE='22023'; END IF;
 ELSE
 IF jsonb_typeof(canonical->k) IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'application_numeric_invalid' USING ERRCODE='22023'; END IF;
 n:=(canonical->>k)::numeric;
 IF n::text IN ('NaN','Infinity','-Infinity') OR n<lo OR (hi IS NOT NULL AND n>hi)
 OR (k IN ('dose_aplicada','area_aplicada_ha','volume_total_aplicado_ml') AND n<=0) THEN RAISE EXCEPTION 'application_numeric_bounds' USING ERRCODE='22023'; END IF;
 END IF;
 END LOOP;
 IF (canonical->>'volume_total_aplicado_ml')::numeric IS DISTINCT FROM (canonical->>'dose_aplicada')::numeric*(canonical->>'area_aplicada_ha')::numeric
 THEN RAISE EXCEPTION 'application_total_invalid' USING ERRCODE='22023'; END IF;
 moment:=(canonical->>'data_aplicacao')::date;
 start_at:=nullif(canonical->>'hora_inicio','')::timestamptz; end_at:=nullif(canonical->>'hora_fim','')::timestamptz;
 IF moment IS NULL OR NOT isfinite(moment) OR (start_at IS NOT NULL AND NOT isfinite(start_at))
 OR (end_at IS NOT NULL AND (NOT isfinite(end_at) OR start_at IS NULL OR end_at<=start_at)) THEN RAISE EXCEPTION 'application_time_invalid' USING ERRCODE='22023'; END IF;
 IF p_rectify_id IS NULL AND cardinality(p_evidencias_manter)>0 THEN RAISE EXCEPTION 'application_inheritance_denied' USING ERRCODE='42501'; END IF;
 count_files:=jsonb_array_length(p_evidencias)+cardinality(p_evidencias_manter);
 IF count_files>20 OR cardinality(p_evidencias_manter)<>(SELECT count(DISTINCT x) FROM unnest(p_evidencias_manter)x)
 THEN RAISE EXCEPTION 'application_evidence_limit' USING ERRCODE='22023'; END IF;
 manifest:='[]'::jsonb;
 FOR ev IN SELECT value FROM jsonb_array_elements(p_evidencias) LOOP
 IF jsonb_typeof(ev) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(ev) key WHERE key NOT IN ('tipo','storage_path','legenda','mime','tamanho_bytes'))
 THEN RAISE EXCEPTION 'application_evidence_invalid' USING ERRCODE='22023'; END IF;
 expected:=CASE ev->>'mime' WHEN 'image/jpeg' THEN 'jpg' WHEN 'image/png' THEN 'png' WHEN 'image/webp' THEN 'webp'
 WHEN 'image/heic' THEN 'heic' WHEN 'image/heif' THEN 'heif' WHEN 'application/pdf' THEN 'pdf'
 WHEN 'video/mp4' THEN 'mp4' WHEN 'video/webm' THEN 'webm' WHEN 'video/quicktime' THEN 'mov'
 WHEN 'audio/mpeg' THEN 'mp3' WHEN 'audio/mp4' THEN 'm4a' WHEN 'audio/wav' THEN 'wav' WHEN 'audio/ogg' THEN 'ogg' WHEN 'audio/webm' THEN 'webm' END;
 IF expected IS NULL OR public.storage1_path_strict(ev->>'storage_path') IS DISTINCT FROM true
 OR split_part(ev->>'storage_path','/',1) IS DISTINCT FROM client::text
 OR split_part(ev->>'storage_path','/',2) IS DISTINCT FROM p_aplicacao_id::text
 OR split_part(ev->>'storage_path','/',3) !~ ('^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.'||expected||'$')
 OR jsonb_typeof(ev->'tamanho_bytes') IS DISTINCT FROM 'number' OR (ev->>'tamanho_bytes')::numeric NOT BETWEEN 1 AND 10485760
 OR (ev->>'tamanho_bytes')::numeric<>trunc((ev->>'tamanho_bytes')::numeric)
 OR coalesce(char_length(ev->>'legenda'),0)>1000
 OR ev->>'tipo' IS DISTINCT FROM (CASE WHEN ev->>'mime' LIKE 'image/%' THEN 'foto' WHEN ev->>'mime' LIKE 'video/%' THEN 'video' WHEN ev->>'mime' LIKE 'audio/%' THEN 'audio' ELSE 'documento' END)
 THEN RAISE EXCEPTION 'application_evidence_invalid' USING ERRCODE='22023'; END IF;
 manifest:=manifest||jsonb_build_array(ev);
 END LOOP;
 IF jsonb_array_length(manifest)<>(SELECT count(DISTINCT value->>'storage_path') FROM jsonb_array_elements(manifest)) THEN RAISE EXCEPTION 'application_evidence_duplicate' USING ERRCODE='22023'; END IF;
 -- One writer per application; then one writer per original version. No global cache.
 PERFORM pg_advisory_xact_lock(hashtextextended('application-save:'||p_aplicacao_id::text,0));
 SELECT * INTO r FROM platform_private.application_save_preparations WHERE application_id=p_aplicacao_id FOR UPDATE;
 IF FOUND AND (r.actor_id IS DISTINCT FROM u OR r.organization_id IS DISTINCT FROM org OR r.payload IS DISTINCT FROM canonical
 OR r.rectify_id IS DISTINCT FROM p_rectify_id OR r.manifest IS DISTINCT FROM manifest OR r.keep_ids IS DISTINCT FROM p_evidencias_manter)
 THEN RAISE EXCEPTION 'application_receipt_mismatch' USING ERRCODE='42501'; END IF;
 IF p_rectify_id IS NOT NULL THEN
 SELECT * INTO original FROM public.aplicacoes WHERE id=p_rectify_id FOR UPDATE;
 IF NOT FOUND OR original.organization_id IS DISTINCT FROM org OR public.can_user_manage_aplicacao(p_rectify_id) IS DISTINCT FROM true
 OR public.can_user_access_aplicacao(p_rectify_id) IS DISTINCT FROM true
 OR original.ordem_servico_id IS DISTINCT FROM osid OR original.ordem_servico_onfarm_id IS DISTINCT FROM onid
 THEN RAISE EXCEPTION 'application_rectification_denied' USING ERRCODE='42501'; END IF;
 IF (r.application_id IS NULL OR r.committed_at IS NULL) AND original.is_latest IS DISTINCT FROM true THEN RAISE EXCEPTION 'application_version_conflict' USING ERRCODE='PT409'; END IF;
 IF char_length(btrim(coalesce(canonical->>'motivo_retificacao',''))) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'application_reason_invalid' USING ERRCODE='22023'; END IF;
 root:=coalesce(original.parent_id,original.id); ver:=original.versao+1;
 END IF;
 -- Validate inherited objects through their immutable origin, never rewritten paths.
 FOREACH kept IN ARRAY p_evidencias_manter LOOP
 SELECT ae.* INTO e FROM public.aplicacao_evidencias ae JOIN public.aplicacao_evidencias_vinculos v ON v.evidencia_id=ae.id
 WHERE v.aplicacao_id=p_rectify_id AND ae.id=kept FOR SHARE OF ae,v;
 IF NOT FOUND OR e.aplicacao_id IS DISTINCT FROM e.versao_origem_id
 OR public.can_user_access_aplicacao(e.versao_origem_id) IS DISTINCT FROM true
 OR split_part(e.storage_path,'/',1) IS DISTINCT FROM client::text OR split_part(e.storage_path,'/',2) IS DISTINCT FROM e.versao_origem_id::text
 OR public.storage1_path_strict(e.storage_path) IS DISTINCT FROM true THEN RAISE EXCEPTION 'application_inheritance_denied' USING ERRCODE='42501'; END IF;
 SELECT * INTO obj FROM storage.objects WHERE bucket_id='aplicacao-evidencias' AND name=e.storage_path FOR SHARE;
 IF NOT FOUND OR obj.metadata->>'mimetype' IS DISTINCT FROM e.mime OR nullif(obj.metadata->>'size','')::bigint IS DISTINCT FROM e.tamanho_bytes
 THEN RAISE EXCEPTION 'application_inherited_object_invalid' USING ERRCODE='42501'; END IF;
 END LOOP;
 IF public.h15_actor_organization() IS DISTINCT FROM org OR public.can_user_create_aplicacao_for_cliente(client) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'application_actor_denied' USING ERRCODE='42501'; END IF;
 IF r.committed_at IS NOT NULL THEN
 SELECT * INTO a FROM public.aplicacoes WHERE id=p_aplicacao_id AND organization_id=org AND created_by=u;
 IF NOT FOUND OR public.can_user_access_aplicacao(p_aplicacao_id) IS DISTINCT FROM true THEN RAISE EXCEPTION 'application_replay_denied' USING ERRCODE='42501'; END IF;
 RETURN jsonb_build_object('success',true,'created',false,'id',a.id,'versao',a.versao,'phase','finalized'); END IF;
 IF r.application_id IS NOT NULL AND r.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'application_preparation_expired' USING ERRCODE='42501'; END IF;
 IF phase='prepare' THEN
 IF r.application_id IS NULL THEN
 IF EXISTS(SELECT 1 FROM public.aplicacoes WHERE id=p_aplicacao_id) THEN RAISE EXCEPTION 'application_identity_conflict' USING ERRCODE='42501'; END IF;
 INSERT INTO platform_private.application_save_preparations(application_id,actor_id,organization_id,client_id,payload,rectify_id,manifest,keep_ids,expires_at)
 VALUES(p_aplicacao_id,u,org,client,canonical,p_rectify_id,manifest,p_evidencias_manter,clock_timestamp()+interval '15 minutes'); END IF;
 RETURN jsonb_build_object('success',true,'id',p_aplicacao_id,'phase','prepared'); END IF;
 IF r.application_id IS NULL THEN RAISE EXCEPTION 'application_preparation_required' USING ERRCODE='42501'; END IF;
 FOR ev IN SELECT value FROM jsonb_array_elements(manifest) LOOP
 SELECT * INTO obj FROM storage.objects WHERE bucket_id='aplicacao-evidencias' AND name=ev->>'storage_path' FOR SHARE;
 IF NOT FOUND OR coalesce(obj.owner_id,obj.owner::text) IS DISTINCT FROM u::text
 OR obj.metadata->>'mimetype' IS DISTINCT FROM ev->>'mime' OR nullif(obj.metadata->>'size','')::bigint IS DISTINCT FROM (ev->>'tamanho_bytes')::bigint
 OR obj.version IS NULL THEN RAISE EXCEPTION 'application_object_denied' USING ERRCODE='42501'; END IF;
 END LOOP;
 -- Metadata and latest-version switch are a single transaction. No OS/communications effects.
 IF p_rectify_id IS NOT NULL THEN UPDATE public.aplicacoes SET is_latest=false WHERE id=p_rectify_id; END IF;
 INSERT INTO public.aplicacoes(id,organization_id,ordem_servico_id,ordem_servico_onfarm_id,data_aplicacao,hora_inicio,hora_fim,responsavel_id,responsavel,modo_aplicacao,produto_usado_id,lote_usado_id,dose_aplicada,volume_calda_l_ha,volume_total_aplicado_ml,area_aplicada_ha,equipamento,equipamento_modelo,bico_tipo,pressao_bar,temperatura_c,umidade_pct,vento_kmh,condicoes_climaticas,latitude,longitude,resultado_inicial,observacoes,created_by,parent_id,versao,motivo_retificacao,is_latest)
 VALUES(p_aplicacao_id,org,osid,onid,moment,start_at,end_at,responsible,name_responsible,nullif(btrim(canonical->>'modo_aplicacao'),''),product,lot,(canonical->>'dose_aplicada')::numeric,(canonical->>'volume_calda_l_ha')::numeric,(canonical->>'volume_total_aplicado_ml')::numeric,(canonical->>'area_aplicada_ha')::numeric,nullif(btrim(canonical->>'equipamento'),''),nullif(btrim(canonical->>'equipamento_modelo'),''),nullif(btrim(canonical->>'bico_tipo'),''),(canonical->>'pressao_bar')::numeric,(canonical->>'temperatura_c')::numeric,(canonical->>'umidade_pct')::numeric,(canonical->>'vento_kmh')::numeric,nullif(btrim(canonical->>'condicoes_climaticas'),''),(canonical->>'latitude')::numeric,(canonical->>'longitude')::numeric,nullif(canonical->>'resultado_inicial',''),nullif(btrim(canonical->>'observacoes'),''),u,root,ver,CASE WHEN p_rectify_id IS NULL THEN NULL ELSE btrim(canonical->>'motivo_retificacao') END,true);
 FOR ev IN SELECT value FROM jsonb_array_elements(manifest) LOOP
 INSERT INTO public.aplicacao_evidencias(aplicacao_id,tipo,storage_path,legenda,mime,tamanho_bytes,created_by,versao_origem_id)
 VALUES(p_aplicacao_id,ev->>'tipo',ev->>'storage_path',nullif(btrim(ev->>'legenda'),''),ev->>'mime',(ev->>'tamanho_bytes')::bigint,u,p_aplicacao_id) RETURNING id INTO ev_id;
 INSERT INTO public.aplicacao_evidencias_vinculos(aplicacao_id,evidencia_id) VALUES(p_aplicacao_id,ev_id);
 END LOOP;
 FOREACH kept IN ARRAY p_evidencias_manter LOOP INSERT INTO public.aplicacao_evidencias_vinculos(aplicacao_id,evidencia_id) VALUES(p_aplicacao_id,kept); END LOOP;
 UPDATE platform_private.application_save_preparations SET committed_at=clock_timestamp() WHERE application_id=p_aplicacao_id;
 RETURN jsonb_build_object('success',true,'created',true,'id',p_aplicacao_id,'versao',ver,'phase','finalized');
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_claim_org_admin_provisioning(p_organization_id uuid, p_email text, p_nome text, p_cpf_cnpj text DEFAULT NULL::text, p_telefone text DEFAULT NULL::text, p_modo_acesso text DEFAULT 'link'::text, p_responsavel_principal boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_email text := lower(btrim(coalesce(p_email,'')));
  v_cpf text := nullif(regexp_replace(coalesce(p_cpf_cnpj,''), '\D', '', 'g'),'');
  v_tel text := nullif(regexp_replace(coalesce(p_telefone,''), '\D', '', 'g'),'');
  v_row public.platform_org_admin_invites%ROWTYPE;
  v_token uuid := gen_random_uuid();
BEGIN
  IF v_actor IS NULL OR NOT public.is_platform_superadmin(v_actor) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin de plataforma' USING ERRCODE='42501';
  END IF;
  IF p_organization_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.organizations o WHERE o.id=p_organization_id AND o.ativo IS TRUE
  ) THEN RAISE EXCEPTION 'platform_invalid: empresa inexistente ou inativa'; END IF;
  IF v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' OR length(v_email)>255
     OR length(btrim(coalesce(p_nome,''))) NOT BETWEEN 3 AND 200 THEN
    RAISE EXCEPTION 'platform_invalid: nome ou e-mail inválido';
  END IF;
  IF v_cpf IS NOT NULL AND length(v_cpf)<>11 THEN RAISE EXCEPTION 'platform_invalid: cpf'; END IF;
  IF v_tel IS NOT NULL AND length(v_tel) NOT IN (10,11) THEN RAISE EXCEPTION 'platform_invalid: telefone'; END IF;
  IF p_modo_acesso NOT IN ('link','senha_temporaria') THEN RAISE EXCEPTION 'platform_invalid: modo'; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(v_email, 0));
  SELECT * INTO v_row FROM public.platform_org_admin_invites WHERE lower(email)=v_email FOR UPDATE;

  IF FOUND THEN
 IF EXISTS(SELECT 1 FROM public.platform_org_admin_email_changes c WHERE c.invite_id=v_row.id AND c.status IN ('requested','auth_updated','failed')) THEN RAISE EXCEPTION 'email_change_pending' USING ERRCODE='55P03'; END IF;
    IF v_row.organization_id <> p_organization_id THEN
      RAISE EXCEPTION 'platform_conflict: e-mail já vinculado a outra empresa' USING ERRCODE='23505';
    END IF;
    IF v_row.status='ativo' THEN
      RETURN jsonb_build_object('job_id',v_row.id,'request_id',v_row.request_id,'status','ativo','user_id',v_row.user_id,'completed',true);
    END IF;
    IF v_row.lease_expires_at IS NOT NULL AND v_row.lease_expires_at > clock_timestamp() THEN
      RAISE EXCEPTION 'platform_conflict: provisionamento em andamento' USING ERRCODE='55P03';
    END IF;
    IF (v_row.nome, v_row.cpf_cnpj, v_row.telefone, v_row.modo_acesso, v_row.responsavel_principal)
       IS DISTINCT FROM (btrim(p_nome), v_cpf, v_tel, p_modo_acesso, p_responsavel_principal) THEN
      RAISE EXCEPTION 'platform_conflict: dados divergentes para o mesmo e-mail' USING ERRCODE='23505';
    END IF;
    UPDATE public.platform_org_admin_invites
       SET status='processando', lease_token=v_token,
           lease_expires_at=clock_timestamp()+interval '2 minutes',
           attempt_count=attempt_count+1, last_error_code=NULL, updated_at=now()
     WHERE id=v_row.id
     RETURNING * INTO v_row;
  ELSE
    INSERT INTO public.platform_org_admin_invites(
      organization_id,user_id,email,nome,cpf_cnpj,telefone,modo_acesso,
