    IF j.organization_id<>p_organization_id THEN RAISE EXCEPTION 'platform_conflict: outro tenant' USING ERRCODE='23505'; END IF;
    IF j.status='ativo' THEN RETURN jsonb_build_object('job_id',j.id,'request_id',j.request_id,'status','ativo','user_id',j.user_id,'completed',true); END IF;
    IF j.lease_expires_at IS NOT NULL AND j.lease_expires_at>clock_timestamp() THEN RAISE EXCEPTION 'platform_conflict: em andamento' USING ERRCODE='55P03'; END IF;
    IF (j.nome,j.cpf_cnpj,j.telefone,j.modo_acesso,j.responsavel_principal) IS DISTINCT FROM (btrim(p_nome),v_cpf,v_tel,p_modo_acesso,p_responsavel_principal) THEN RAISE EXCEPTION 'platform_conflict: dados divergentes' USING ERRCODE='23505'; END IF;
    IF p_delivery_mode='email' THEN
      v_ambiguous := j.email_delivery_status='ambiguous' OR (
        j.email_delivery_status='failed' AND j.email_last_error_code IN (
          'email_unknown_error','email_send_ambiguous','email_accept_persistence_failed',
          'email_timeout','email_network_error','email_send_crash','email_delivery_setup_failed'
        )
      );
      IF v_ambiguous AND NOT coalesce(p_confirm_ambiguous_email_retry,false) THEN
        RAISE EXCEPTION 'email_ambiguous_confirmation_required' USING ERRCODE='P0001';
      END IF;
      IF j.email_next_attempt_at > clock_timestamp() THEN
        RAISE EXCEPTION 'platform_email_cooldown: reenvio em cooldown' USING ERRCODE='55P03';
      END IF;
    END IF;
    UPDATE public.platform_org_admin_invites
       SET status='processando',lease_token=token,lease_expires_at=clock_timestamp()+interval '2 minutes',attempt_count=attempt_count+1,last_error_code=NULL,updated_at=now()
     WHERE id=j.id RETURNING * INTO j;
  ELSE
    INSERT INTO public.platform_org_admin_invites(organization_id,user_id,email,nome,cpf_cnpj,telefone,modo_acesso,responsavel_principal,invited_by,status,request_id,attempt_count,lease_token,lease_expires_at,updated_at)
    VALUES(p_organization_id,NULL,v_email,btrim(p_nome),v_cpf,v_tel,p_modo_acesso,p_responsavel_principal,p_actor_id,'processando',gen_random_uuid(),1,token,clock_timestamp()+interval '2 minutes',now()) RETURNING * INTO j;
  END IF;
  RETURN jsonb_build_object('job_id',j.id,'request_id',j.request_id,'status',j.status,'lease_token',token,'lease_expires_at',j.lease_expires_at,'user_id',j.user_id,'completed',false);
END
$function$

CREATE OR REPLACE FUNCTION public.rpc_fiscal_event_sefaz_prepare_v1(_invoice_id uuid, _event_kind text, _reason text, _idempotency_key text, _actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_ref text; v_prod boolean; v_tpamb text; v_inv public.fiscal_invoices; v_actor_org uuid; v_code text; v_type text; v_reason text:=btrim(coalesce(_reason,'')); v_fp text; v_prev public.fiscal_events; v_seq integer; v_id uuid; v_prot text;
BEGIN
 IF _actor IS NULL OR _actor IS DISTINCT FROM auth.uid() OR NOT public.fn_fiscal_can_operate(_actor) THEN RAISE EXCEPTION 'FISCAL_FORBIDDEN' USING ERRCODE='42501'; END IF;
 v_actor_org:=public.h15_actor_organization(); IF v_actor_org IS NULL THEN RAISE EXCEPTION 'FISCAL_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF coalesce(btrim(_idempotency_key),'')='' OR length(_idempotency_key)>200 THEN RAISE EXCEPTION 'FISCAL_EVENT_IDEMPOTENCY_INVALID'; END IF;
 SELECT project_ref,production_emission_allowed INTO v_ref,v_prod FROM public.fiscal_environment_marker LIMIT 1;
 IF v_ref IS DISTINCT FROM 'swzpzcwiasxmjutrmvkm' OR coalesce(v_prod,true) THEN RAISE EXCEPTION 'FISCAL_PRODUCTION_ENDPOINT_BLOCKED'; END IF;
 SELECT * INTO v_inv FROM public.fiscal_invoices WHERE id=_invoice_id AND organization_id=v_actor_org;
 IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_EVENT_INVOICE_NOT_FOUND' USING ERRCODE='42501'; END IF;
 SELECT nfe_environment_code INTO v_tpamb FROM public.company_fiscal_settings WHERE id=v_inv.company_settings_id AND organization_id=v_actor_org AND is_active;
 IF v_tpamb IS DISTINCT FROM '2' THEN RAISE EXCEPTION 'FISCAL_PRODUCTION_ENDPOINT_BLOCKED'; END IF;
 IF _event_kind='CANCELLATION' THEN v_code:='110111';v_type:='SEFAZ_CANCELLATION_PREPARED'; ELSIF _event_kind='CORRECTION' THEN v_code:='110110';v_type:='SEFAZ_CORRECTION_PREPARED'; ELSE RAISE EXCEPTION 'FISCAL_EVENT_TYPE_UNSUPPORTED'; END IF;
 IF coalesce(v_inv.access_key,'') !~ '^[0-9]{44}$' THEN RAISE EXCEPTION 'FISCAL_EVENT_ACCESS_KEY_INVALID'; END IF;
 IF coalesce(v_inv.environment,'HOMOLOGATION')<>'HOMOLOGATION' THEN RAISE EXCEPTION 'FISCAL_PRODUCTION_ENDPOINT_BLOCKED'; END IF;
 SELECT n_prot INTO v_prot FROM public.fiscal_sefaz_transmissions WHERE fiscal_invoice_id=_invoice_id AND service IN ('NFeAutorizacao4','NFeRetAutorizacao4') AND state='SUCCEEDED' AND outcome='AUTHORIZED' AND n_prot IS NOT NULL AND ch_nfe=v_inv.access_key ORDER BY created_at DESC LIMIT 1;
 IF v_prot IS NULL THEN RAISE EXCEPTION 'FISCAL_EVENT_INVOICE_NOT_AUTHORIZED'; END IF;
 IF _event_kind='CANCELLATION' THEN IF length(v_reason)<15 OR length(v_reason)>255 THEN RAISE EXCEPTION 'FISCAL_EVENT_REASON_INVALID'; END IF; IF EXISTS(SELECT 1 FROM public.v_fiscal_sefaz_event_state WHERE fiscal_invoice_id=_invoice_id AND sefaz_event_code='110111' AND state='REGISTERED') THEN RAISE EXCEPTION 'FISCAL_EVENT_ALREADY_REGISTERED'; END IF;
 ELSE IF length(v_reason)<15 OR length(v_reason)>1000 THEN RAISE EXCEPTION 'FISCAL_EVENT_REASON_INVALID'; END IF; IF EXISTS(SELECT 1 FROM public.v_fiscal_sefaz_event_state WHERE fiscal_invoice_id=_invoice_id AND sefaz_event_code='110111' AND state='REGISTERED') THEN RAISE EXCEPTION 'FISCAL_EVENT_INVOICE_CANCELED'; END IF; END IF;
 v_fp:=encode(extensions.digest(v_code||'|'||v_inv.access_key||'|'||v_reason,'sha256'),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended('fiscal_sefaz_event:'||_invoice_id::text||':'||_idempotency_key,0));
 SELECT * INTO v_prev FROM public.fiscal_events WHERE fiscal_invoice_id=_invoice_id AND organization_id=v_actor_org AND event_type=v_type AND idempotency_key=_idempotency_key;
 IF FOUND THEN IF v_prev.payload_fingerprint IS DISTINCT FROM v_fp THEN RAISE EXCEPTION 'FISCAL_EVENT_IDEMPOTENCY_MISMATCH'; END IF; RETURN jsonb_build_object('eventId',v_prev.id,'eventCode',v_prev.sefaz_event_code,'seqEvento',v_prev.sefaz_seq_evento,'accessKey',v_prev.sefaz_access_key,'reason',v_prev.sefaz_reason,'protocol',v_prot,'companySettingsId',v_inv.company_settings_id,'idempotentReplay',true); END IF;
 SELECT coalesce(max(sefaz_seq_evento),0)+1 INTO v_seq FROM public.fiscal_events WHERE fiscal_invoice_id=_invoice_id AND organization_id=v_actor_org AND sefaz_event_code=v_code;
 IF v_seq>20 THEN RAISE EXCEPTION 'FISCAL_EVENT_SEQUENCE_EXHAUSTED'; END IF;
 INSERT INTO public.fiscal_events(fiscal_invoice_id,event_type,event_source,performed_by,idempotency_key,payload_fingerprint,notes,sefaz_event_code,sefaz_seq_evento,sefaz_access_key,sefaz_reason,request_snapshot,organization_id)
 VALUES(_invoice_id,v_type,'INTERNAL',_actor,_idempotency_key,v_fp,left(v_reason,2000),v_code,v_seq,v_inv.access_key,v_reason,jsonb_build_object('eventKind',_event_kind,'protocol',v_prot,'environmentCode','2'),v_actor_org) RETURNING id INTO v_id;
 RETURN jsonb_build_object('eventId',v_id,'eventCode',v_code,'seqEvento',v_seq,'accessKey',v_inv.access_key,'reason',v_reason,'protocol',v_prot,'companySettingsId',v_inv.company_settings_id,'idempotentReplay',false);
END $function$

CREATE OR REPLACE FUNCTION public.platform_publish_plan_version_draft(_draft_id uuid, _reason text, _idempotency_key uuid, _confirmation text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v public.saas_plan_versions%ROWTYPE;
  prev public.saas_plan_versions%ROWTYPE;
  v_check jsonb; v_reason text; v_open int; v_prev_new jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501';
  END IF;
  IF _confirmation IS DISTINCT FROM 'PUBLICAR' THEN
    RAISE EXCEPTION 'platform_invalid: confirmação inválida' USING ERRCODE='22023';
  END IF;
  IF _idempotency_key IS NULL THEN
    RAISE EXCEPTION 'platform_invalid: chave idempotente obrigatória' USING ERRCODE='22023';
  END IF;
  v_reason := platform_private.normalize_commercial_reason(_reason);

  SELECT * INTO v FROM public.saas_plan_versions WHERE id=_draft_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: rascunho inexistente' USING ERRCODE='22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('saas_plan_version:' || v.plan_id::text,0));
  SELECT * INTO v FROM public.saas_plan_versions WHERE id=_draft_id FOR UPDATE;

  IF v.status='PUBLISHED' AND v.publish_key=_idempotency_key THEN
    IF v.publication_reason IS DISTINCT FROM v_reason THEN
      RAISE EXCEPTION 'platform_conflict: mesma chave idempotente com motivo divergente' USING ERRCODE='40001';
    END IF;
    RETURN v.id;
  END IF;
  IF EXISTS (SELECT 1 FROM public.saas_plan_versions x WHERE x.publish_key=_idempotency_key AND x.id<>v.id) THEN
    RAISE EXCEPTION 'platform_conflict: chave idempotente já usada em outra publicação' USING ERRCODE='40001';
  END IF;
  IF v.status <> 'DRAFT' THEN RAISE EXCEPTION 'platform_conflict: versão não está em rascunho' USING ERRCODE='40001'; END IF;

  v_check := public.platform_validate_plan_version_draft(v.id);
  IF NOT coalesce((v_check->>'complete')::boolean,false) OR NOT coalesce((v_check->>'valid')::boolean,false) THEN
    RAISE EXCEPTION 'platform_invalid: rascunho incompleto ou inválido' USING ERRCODE='22023';
  END IF;

  SELECT count(*) INTO v_open FROM public.saas_plan_versions
   WHERE plan_id=v.plan_id AND status='PUBLISHED' AND effective_to IS NULL;
  IF v_open > 1 THEN
    RAISE EXCEPTION 'platform_conflict: mais de uma versão vigente para o plano' USING ERRCODE='40001';
  END IF;
  IF EXISTS (SELECT 1 FROM public.saas_plan_versions x WHERE x.plan_id=v.plan_id AND x.status='PUBLISHED'
              AND x.effective_from >= v.effective_from) THEN
    RAISE EXCEPTION 'platform_conflict: início da vigência deve ser posterior ao da versão publicada anterior' USING ERRCODE='40001';
  END IF;
  IF EXISTS (SELECT 1 FROM public.saas_plan_versions x WHERE x.plan_id=v.plan_id AND x.status='PUBLISHED'
              AND x.effective_to IS NOT NULL AND x.effective_to > v.effective_from) THEN
    RAISE EXCEPTION 'platform_conflict: vigência sobreposta' USING ERRCODE='40001';
  END IF;

  SELECT * INTO prev FROM public.saas_plan_versions
   WHERE plan_id=v.plan_id AND status='PUBLISHED' AND effective_to IS NULL FOR UPDATE;
  IF FOUND THEN
    PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_supersede',prev.id);
    UPDATE public.saas_plan_versions SET effective_to = v.effective_from WHERE id = prev.id;
    SELECT to_jsonb(x) INTO v_prev_new FROM public.saas_plan_versions x WHERE x.id=prev.id;
    PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_audit',v.plan_id);
    INSERT INTO public.saas_plan_version_audit(plan_version_id,action,old_values,new_values,reason,origin,actor_user_id,idempotency_key)
    VALUES(prev.id,'superseded',to_jsonb(prev),v_prev_new || jsonb_build_object('superseded_by',v.id),
           v_reason,'platform_rpc',auth.uid(),_idempotency_key);
  END IF;

  PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_write',v.plan_id);
  UPDATE public.saas_plan_versions SET status='PUBLISHED',published_at=now(),publication_reason=v_reason,
    publish_key=_idempotency_key WHERE id=v.id;
  PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_audit',v.plan_id);
  INSERT INTO public.saas_plan_version_audit(plan_version_id,action,old_values,new_values,reason,origin,actor_user_id,idempotency_key)
  VALUES(v.id,'published',to_jsonb(v),
         (SELECT to_jsonb(x) FROM public.saas_plan_versions x WHERE x.id=v.id) || jsonb_build_object('supersedes',prev.id),
         v_reason,'platform_rpc',auth.uid(),_idempotency_key);
  RETURN v.id;
END; $function$

CREATE OR REPLACE FUNCTION platform_private.set_org_principal_admin_core(_org uuid, _user_id uuid, _motivo text, _expected_responsavel uuid, _idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE o public.organizations%ROWTYPE; a public.platform_org_admin_audit%ROWTYPE; v_motivo text; v_old uuid;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501'; END IF;
  IF _idempotency_key IS NULL OR _org IS NULL OR _user_id IS NULL THEN
    RAISE EXCEPTION 'platform_invalid: parâmetros obrigatórios' USING ERRCODE='22023'; END IF;
  v_motivo := btrim(coalesce(_motivo,''));
  IF v_motivo = '' THEN v_motivo := 'Alteração de responsável principal'; END IF;
  IF char_length(v_motivo) < 2 THEN RAISE EXCEPTION 'platform_invalid: motivo obrigatório (mínimo 2 caracteres)' USING ERRCODE='22023'; END IF;

  SELECT * INTO o FROM public.organizations WHERE id=_org FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: empresa inexistente' USING ERRCODE='22023'; END IF;

  SELECT * INTO a FROM public.platform_org_admin_audit WHERE action='principal_transferred' AND idempotency_key=_idempotency_key;
  IF FOUND THEN
    IF a.organization_id=_org AND a.target_user_id=_user_id AND a.reason=v_motivo THEN
      RETURN jsonb_build_object('organization_id',_org,'responsavel_user_id',_user_id,'idempotent',true); END IF;
    RAISE EXCEPTION 'platform_conflict: chave idempotente já usada com outro conteúdo' USING ERRCODE='40001';
  END IF;

  IF o.responsavel_user_id IS DISTINCT FROM _expected_responsavel THEN
    RAISE EXCEPTION 'platform_conflict: o responsável foi alterado por outra pessoa; recarregue' USING ERRCODE='40001'; END IF;
  IF o.responsavel_user_id = _user_id THEN
    RAISE EXCEPTION 'platform_invalid: este administrador já é o responsável principal' USING ERRCODE='22023'; END IF;
  IF public.is_platform_superadmin(_user_id)
     OR NOT EXISTS (SELECT 1 FROM public.platform_org_admin_invites i WHERE i.organization_id=_org AND i.user_id=_user_id AND i.status='ativo')
     OR NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.user_id=_user_id AND p.organization_id=_org AND p.ativo IS TRUE)
     OR NOT public.has_role(_user_id,'administrador'::public.app_role) THEN
    RAISE EXCEPTION 'platform_invalid: candidato precisa ser administrador ativo desta empresa' USING ERRCODE='22023'; END IF;

  v_old := o.responsavel_user_id;
  PERFORM platform_private.issue_ticket('org_write', _org);
  UPDATE public.organizations SET responsavel_user_id=_user_id, responsavel_definido_em=now(), updated_at=now() WHERE id=_org;
  UPDATE public.platform_org_admin_invites SET responsavel_principal = coalesce(user_id=_user_id,false), updated_at=now()
   WHERE organization_id=_org AND responsavel_principal IS DISTINCT FROM coalesce(user_id=_user_id,false);
  UPDATE public.profiles SET cargo = CASE WHEN user_id=_user_id THEN 'Responsável Principal' ELSE 'Administrador' END
   WHERE organization_id=_org AND user_id IN (_user_id, v_old) AND cargo IN ('Responsável Principal','Administrador')
     AND cargo IS DISTINCT FROM CASE WHEN user_id=_user_id THEN 'Responsável Principal' ELSE 'Administrador' END;

  INSERT INTO public.platform_org_admin_audit(organization_id,target_user_id,actor_user_id,action,status,reason,origin,idempotency_key,old_values,new_values)
  VALUES (_org,_user_id,auth.uid(),'principal_transferred','succeeded',v_motivo,'platform_rpc',_idempotency_key,
          jsonb_build_object('responsavel_user_id',v_old,'responsavel_definido_em',o.responsavel_definido_em),
          jsonb_build_object('responsavel_user_id',_user_id));
  RETURN jsonb_build_object('organization_id',_org,'responsavel_user_id',_user_id,'idempotent',false);
END $function$

CREATE OR REPLACE FUNCTION platform_private.update_org_admin_core(_invite_id uuid, _nome text, _telefone text, _cpf text, _motivo text, _expected_updated_at timestamp with time zone, _idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE j public.platform_org_admin_invites%ROWTYPE; a public.platform_org_admin_audit%ROWTYPE;
  v_motivo text; v_nome text; v_tel text; v_cpf text; v_old jsonb; v_new jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501'; END IF;
  IF _idempotency_key IS NULL OR _invite_id IS NULL THEN RAISE EXCEPTION 'platform_invalid: parâmetros obrigatórios' USING ERRCODE='22023'; END IF;
  v_motivo := btrim(coalesce(_motivo,''));
  IF char_length(v_motivo) = 1 THEN RAISE EXCEPTION 'platform_invalid: se informar o motivo, use ao menos 2 caracteres' USING ERRCODE='22023'; END IF;
  v_nome := regexp_replace(btrim(coalesce(_nome,'')), '\s+', ' ', 'g');
  v_tel := nullif(regexp_replace(coalesce(_telefone,''),'\D','','g'),'');
  v_cpf := nullif(regexp_replace(coalesce(_cpf,''),'\D','','g'),'');
  IF char_length(v_nome) NOT BETWEEN 3 AND 200 THEN RAISE EXCEPTION 'platform_invalid: nome inválido' USING ERRCODE='22023'; END IF;
  IF v_tel IS NOT NULL AND length(v_tel) NOT IN (10,11) THEN RAISE EXCEPTION 'platform_invalid: telefone inválido' USING ERRCODE='22023'; END IF;
  IF v_cpf IS NOT NULL AND (length(v_cpf)<>11 OR v_cpf ~ '^(\d)\1{10}$') THEN RAISE EXCEPTION 'platform_invalid: CPF inválido' USING ERRCODE='22023'; END IF;

  SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=_invite_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: administrador inexistente' USING ERRCODE='22023'; END IF;

  SELECT * INTO a FROM public.platform_org_admin_audit WHERE action='admin_profile_updated' AND idempotency_key=_idempotency_key;
  IF FOUND THEN
    IF a.invite_id=_invite_id AND a.reason=v_motivo AND a.new_values->>'nome' IS NOT DISTINCT FROM v_nome
       AND a.new_values->>'telefone' IS NOT DISTINCT FROM v_tel AND a.new_values->>'cpf_cnpj' IS NOT DISTINCT FROM v_cpf THEN
      RETURN jsonb_build_object('invite_id',_invite_id,'updated_at',j.updated_at,'idempotent',true); END IF;
    RAISE EXCEPTION 'platform_conflict: chave idempotente já usada com outro conteúdo' USING ERRCODE='40001';
  END IF;

  IF j.status='processando' OR (j.lease_expires_at IS NOT NULL AND j.lease_expires_at > clock_timestamp()) THEN
    RAISE EXCEPTION 'platform_conflict: provisionamento em andamento' USING ERRCODE='55P03'; END IF;
  IF _expected_updated_at IS NULL OR j.updated_at IS DISTINCT FROM _expected_updated_at THEN
    RAISE EXCEPTION 'platform_conflict: o administrador foi alterado por outra pessoa; recarregue antes de salvar' USING ERRCODE='40001'; END IF;
  IF j.user_id IS NOT NULL AND public.is_platform_superadmin(j.user_id) THEN
    RAISE EXCEPTION 'platform_forbidden: acesso de plataforma não é editável aqui' USING ERRCODE='42501'; END IF;
  IF v_cpf IS DISTINCT FROM j.cpf_cnpj AND j.status='ativo' AND j.cpf_cnpj IS NOT NULL THEN
    RAISE EXCEPTION 'platform_invalid: correção de CPF de administrador ativo exige fluxo específico' USING ERRCODE='22023'; END IF;
  IF (v_nome, v_tel, v_cpf) IS NOT DISTINCT FROM (j.nome, j.telefone, j.cpf_cnpj) THEN
    RAISE EXCEPTION 'platform_invalid: nenhuma alteração para salvar' USING ERRCODE='22023'; END IF;

  v_old := jsonb_build_object('nome',j.nome,'telefone',j.telefone,'cpf_cnpj',j.cpf_cnpj);
  UPDATE public.platform_org_admin_invites SET nome=v_nome, telefone=v_tel, cpf_cnpj=v_cpf,
         updated_at=greatest(clock_timestamp(), j.updated_at + interval '1 microsecond')
   WHERE id=_invite_id RETURNING * INTO j;
  IF j.user_id IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM public.profiles p WHERE p.user_id=j.user_id AND p.organization_id IS DISTINCT FROM j.organization_id) THEN
      RAISE EXCEPTION 'platform_conflict: vínculo do perfil diverge da empresa' USING ERRCODE='40001'; END IF;
    UPDATE public.profiles SET nome=v_nome, telefone=v_tel, cpf_cnpj=v_cpf
     WHERE user_id=j.user_id AND organization_id=j.organization_id;
  END IF;
  v_new := jsonb_build_object('nome',v_nome,'telefone',v_tel,'cpf_cnpj',v_cpf);
  INSERT INTO public.platform_org_admin_audit(organization_id,target_user_id,invite_id,actor_user_id,action,status,reason,origin,idempotency_key,old_values,new_values)
  VALUES (j.organization_id,j.user_id,_invite_id,auth.uid(),'admin_profile_updated','succeeded',v_motivo,'platform_rpc',_idempotency_key,v_old,v_new);
  RETURN jsonb_build_object('invite_id',_invite_id,'updated_at',j.updated_at,'idempotent',false);
END $function$

CREATE OR REPLACE FUNCTION public.platform_begin_org_admin_email_change(p_actor_id uuid, p_invite_id uuid, p_new_email text, p_reason text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE j public.platform_org_admin_invites%ROWTYPE; c public.platform_org_admin_email_changes%ROWTYPE;
  v_email text := lower(btrim(coalesce(p_new_email,''))); v_reason text := btrim(coalesce(p_reason,''));
BEGIN
 PERFORM platform_private.require_provisioned_admin_target(p_actor_id,p_invite_id);
  PERFORM platform_private.require_service_role();
  IF p_actor_id IS NULL OR NOT public.is_platform_superadmin(p_actor_id) THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
  IF p_idempotency_key IS NULL OR p_invite_id IS NULL THEN RAISE EXCEPTION 'platform_invalid: parâmetros' USING ERRCODE='22023'; END IF;
  IF v_reason = '' THEN v_reason := 'Alteração de e-mail administrativo'; END IF;
  IF char_length(v_reason) < 2 THEN RAISE EXCEPTION 'platform_invalid: motivo' USING ERRCODE='22023'; END IF;
  IF v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' OR length(v_email) > 254 THEN RAISE EXCEPTION 'platform_invalid: email' USING ERRCODE='22023'; END IF;

  SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=p_invite_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: administrador' USING ERRCODE='22023'; END IF;

  SELECT * INTO c FROM public.platform_org_admin_email_changes WHERE idempotency_key=p_idempotency_key FOR UPDATE;
  IF FOUND THEN
    IF c.invite_id<>p_invite_id OR c.new_email<>v_email OR c.reason<>v_reason THEN
      RAISE EXCEPTION 'platform_conflict: chave idempotente já usada com outro conteúdo' USING ERRCODE='40001'; END IF;
    IF c.status='cancelled' THEN RAISE EXCEPTION 'platform_conflict: solicitação substituída' USING ERRCODE='40001'; END IF;
    IF c.status='failed' THEN
      UPDATE public.platform_org_admin_email_changes SET status='requested', attempt_count=attempt_count+1, updated_at=now()
       WHERE id=c.id RETURNING * INTO c;
    END IF;
    RETURN jsonb_build_object('op_id',c.id,'status',c.status,'user_id',c.user_id,'old_email',c.old_email,'new_email',c.new_email,
      'invite_status',c.invite_status_at_request,'organization_id',c.organization_id,'attempt',c.attempt_count,'idempotent',true);
  END IF;

  PERFORM platform_private.cancel_stale_email_change(p_invite_id, p_actor_id);
  IF EXISTS (SELECT 1 FROM public.platform_org_admin_email_changes x WHERE x.invite_id=p_invite_id AND x.status IN ('requested','auth_updated','failed')) THEN
    RAISE EXCEPTION 'platform_conflict: já existe mudança de e-mail pendente para este administrador' USING ERRCODE='55P03'; END IF;
  IF j.status='processando' OR (j.lease_expires_at IS NOT NULL AND j.lease_expires_at > clock_timestamp())
     OR j.email_delivery_status='sending' THEN
    RAISE EXCEPTION 'platform_conflict: provisionamento em andamento' USING ERRCODE='55P03'; END IF;
  IF j.user_id IS NOT NULL AND public.is_platform_superadmin(j.user_id) THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
  IF j.user_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.user_id=j.user_id AND p.organization_id=j.organization_id) THEN
    RAISE EXCEPTION 'platform_conflict: vínculo do perfil diverge da empresa' USING ERRCODE='40001'; END IF;
  IF lower(j.email)=v_email THEN RAISE EXCEPTION 'platform_invalid: e-mail igual ao atual' USING ERRCODE='22023'; END IF;
  IF EXISTS (SELECT 1 FROM public.platform_org_admin_invites i WHERE lower(i.email)=v_email)
     OR EXISTS (SELECT 1 FROM public.profiles p WHERE lower(p.email)=v_email AND p.user_id IS DISTINCT FROM j.user_id)
     OR EXISTS (SELECT 1 FROM auth.users u WHERE lower(u.email)=v_email AND u.id IS DISTINCT FROM j.user_id)
     OR EXISTS (SELECT 1 FROM public.platform_org_admin_email_changes x WHERE x.new_email=v_email AND x.status IN ('requested','auth_updated','failed')) THEN
    RAISE EXCEPTION 'platform_email_in_use' USING ERRCODE='23505'; END IF;

  INSERT INTO public.platform_org_admin_email_changes(idempotency_key,organization_id,invite_id,user_id,invite_status_at_request,old_email,new_email,reason,actor_user_id,status)
  VALUES (p_idempotency_key,j.organization_id,j.id,j.user_id,j.status,lower(j.email),v_email,v_reason,p_actor_id,'requested') RETURNING * INTO c;
  INSERT INTO public.platform_org_admin_audit(organization_id,target_user_id,invite_id,actor_user_id,action,status,reason,origin,idempotency_key,old_values,new_values)
  VALUES (j.organization_id,j.user_id,j.id,p_actor_id,'email_change_requested','requested',v_reason,'edge_platform_org_admin_email_change',p_idempotency_key,
          jsonb_build_object('email',lower(j.email),'invite_status',j.status),jsonb_build_object('email',v_email));
  RETURN jsonb_build_object('op_id',c.id,'status',c.status,'user_id',c.user_id,'old_email',c.old_email,'new_email',c.new_email,
    'invite_status',c.invite_status_at_request,'organization_id',c.organization_id,'attempt',c.attempt_count,'idempotent',false);
END $function$

CREATE OR REPLACE FUNCTION platform_private.update_organization_profile_core(_org uuid, _razao_social text, _nome_fantasia text, _email text, _motivo text, _expected_updated_at timestamp with time zone, _idempotency_key uuid, _dados jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  o public.organizations%ROWTYPE; a public.organization_profile_audit%ROWTYPE;
  v_razao text; v_fant text; v_email text; v_motivo text; v_old jsonb; v_new jsonb;
  v_patch jsonb; v_dold jsonb; v_dnew jsonb; v_fuso text; k text; v text;
  v_chg_old jsonb := '{}'::jsonb; v_chg_new jsonb := '{}'::jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501'; END IF;
  IF _idempotency_key IS NULL THEN RAISE EXCEPTION 'platform_invalid: chave idempotente obrigatória' USING ERRCODE='22023'; END IF;
  v_motivo := btrim(coalesce(_motivo,''));
  IF char_length(v_motivo) < 2 THEN RAISE EXCEPTION 'platform_invalid: motivo obrigatório (mínimo 2 caracteres)' USING ERRCODE='22023'; END IF;
  v_razao := regexp_replace(btrim(coalesce(_razao_social,'')), '\s+', ' ', 'g');
  v_fant  := nullif(regexp_replace(btrim(coalesce(_nome_fantasia,'')), '\s+', ' ', 'g'), '');
  v_email := lower(btrim(coalesce(_email,'')));
  IF char_length(v_razao) < 2 OR char_length(v_razao) > 200 THEN RAISE EXCEPTION 'platform_invalid: razão social inválida' USING ERRCODE='22023'; END IF;
  IF v_fant IS NOT NULL AND char_length(v_fant) > 200 THEN RAISE EXCEPTION 'platform_invalid: nome fantasia inválido' USING ERRCODE='22023'; END IF;
  IF v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' OR char_length(v_email) > 254 THEN RAISE EXCEPTION 'platform_invalid: e-mail inválido' USING ERRCODE='22023'; END IF;
  BEGIN
    v_patch := platform_private.org_cadastro_patch(_dados);
  EXCEPTION WHEN raise_exception THEN
    RAISE EXCEPTION 'platform_invalid: %', replace(SQLERRM,'org_invalid: ','') USING ERRCODE='22023';
  END;

  SELECT * INTO o FROM public.organizations WHERE id=_org FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: empresa inexistente' USING ERRCODE='22023'; END IF;

  SELECT * INTO a FROM public.organization_profile_audit WHERE idempotency_key=_idempotency_key;
  IF FOUND THEN
    IF a.organization_id=_org AND a.reason=v_motivo
       AND a.new_values->>'razao_social' IS NOT DISTINCT FROM v_razao
       AND a.new_values->>'nome_fantasia' IS NOT DISTINCT FROM v_fant
       AND a.new_values->>'email_corporativo' IS NOT DISTINCT FROM v_email
       AND coalesce(a.new_values->'dados_patch','{}'::jsonb) = v_patch THEN
      RETURN jsonb_build_object('organization_id',_org,'updated_at',o.updated_at,'idempotent',true);
    END IF;
    RAISE EXCEPTION 'platform_conflict: chave idempotente já usada com outro conteúdo' USING ERRCODE='40001';
  END IF;

  IF _expected_updated_at IS NULL OR o.updated_at IS DISTINCT FROM _expected_updated_at THEN
    RAISE EXCEPTION 'platform_conflict: a empresa foi alterada por outra pessoa; recarregue antes de salvar' USING ERRCODE='40001';
  END IF;

  -- Merge seguro: preserva chaves não enviadas/desconhecidas; '' remove só a chave enviada.
  v_dold := coalesce(o.onboarding_dados,'{}'::jsonb);
  v_dnew := v_dold;
  FOR k, v IN SELECT key, value #>> '{}' FROM jsonb_each(v_patch) LOOP
    IF v = '' THEN v_dnew := v_dnew - k; ELSE v_dnew := v_dnew || jsonb_build_object(k, v); END IF;
    IF (v_dold->>k) IS DISTINCT FROM (v_dnew->>k) THEN
      v_chg_old := v_chg_old || jsonb_build_object(k, v_dold->k);
      v_chg_new := v_chg_new || jsonb_build_object(k, v_dnew->k);
    END IF;
  END LOOP;
  v_fuso := CASE WHEN v_patch ? 'fuso_horario' THEN nullif(v_patch->>'fuso_horario','') ELSE o.fuso_horario END;

  IF o.razao_social IS NOT DISTINCT FROM v_razao AND o.nome IS NOT DISTINCT FROM v_razao
     AND o.nome_fantasia IS NOT DISTINCT FROM v_fant AND o.email_corporativo IS NOT DISTINCT FROM v_email
     AND v_chg_new = '{}'::jsonb AND o.fuso_horario IS NOT DISTINCT FROM v_fuso THEN
    RAISE EXCEPTION 'platform_invalid: nenhuma alteração para salvar' USING ERRCODE='22023';
  END IF;

  v_old := jsonb_build_object('razao_social',o.razao_social,'nome',o.nome,'nome_fantasia',o.nome_fantasia,'email_corporativo',o.email_corporativo,'fuso_horario',o.fuso_horario,'dados',v_chg_old,'updated_at',o.updated_at);
  PERFORM platform_private.issue_ticket('org_write', _org);
  UPDATE public.organizations SET razao_social=v_razao, nome=v_razao, nome_fantasia=v_fant,
    email_corporativo=v_email, fuso_horario=v_fuso, onboarding_dados=v_dnew, updated_at=now()
   WHERE id=_org RETURNING * INTO o;
  v_new := jsonb_build_object('razao_social',o.razao_social,'nome',o.nome,'nome_fantasia',o.nome_fantasia,'email_corporativo',o.email_corporativo,'fuso_horario',o.fuso_horario,'dados',v_chg_new,'dados_patch',v_patch,'updated_at',o.updated_at);
  INSERT INTO public.organization_profile_audit(organization_id,actor_user_id,origin,reason,idempotency_key,old_values,new_values)
  VALUES (_org, auth.uid(), 'platform_rpc', v_motivo, _idempotency_key, v_old, v_new);
  RETURN jsonb_build_object('organization_id',_org,'updated_at',o.updated_at,'idempotent',false);
END $function$
